pub const JoinSide = enum {
    left,
    right,
};

pub const QueryOrderKey = union(enum) {
    missing,
    null,
    bool: bool,
    number: f64,
    string: []const u8,
    json: []const u8,
};

pub const ScalarComparison = enum { lt, eq, gt };

pub fn cloneQueryOrderKeysAlloc(
    alloc: Allocator,
    source: []const QueryOrderKey,
) ![]QueryOrderKey {
    if (source.len == 0) return &.{};
    const keys = try alloc.alloc(QueryOrderKey, source.len);
    var initialized: usize = 0;
    errdefer {
        freeQueryOrderKeys(alloc, keys[0..initialized]);
        alloc.free(keys);
    }
    for (source) |key| {
        keys[initialized] = switch (key) {
            .missing => .missing,
            .null => .null,
            .bool => |value| .{ .bool = value },
            .number => |value| .{ .number = value },
            .string => |value| .{ .string = try alloc.dupe(u8, value) },
            .json => |value| .{ .json = try alloc.dupe(u8, value) },
        };
        initialized += 1;
    }
    return keys;
}

pub fn freeQueryOrderKeys(alloc: Allocator, keys: []const QueryOrderKey) void {
    for (keys) |key| switch (key) {
        .string, .json => |text| alloc.free(text),
        else => {},
    };
}

pub const relationalStoreRowValueAlloc = relational_store_mod.relationalStoreRowValueAlloc;

pub fn freeQueryOrderKeySlice(alloc: Allocator, keys: []const QueryOrderKey) void {
    freeQueryOrderKeys(alloc, keys);
    if (keys.len > 0) alloc.free(keys);
}

pub fn compareQueryOrderKeys(lhs: QueryOrderKey, rhs: QueryOrderKey) ScalarComparison {
    return compareQueryOrderKeysWithCollation(lhs, rhs, null);
}

pub fn compareQueryOrderKeysWithCollation(lhs: QueryOrderKey, rhs: QueryOrderKey, collation: ?[]const u8) ScalarComparison {
    const left_rank = queryOrderKeyRank(lhs);
    const right_rank = queryOrderKeyRank(rhs);
    if (left_rank != right_rank) return if (left_rank < right_rank) .lt else .gt;
    return switch (lhs) {
        .missing, .null => .eq,
        .bool => |left| blk: {
            const right = rhs.bool;
            if (left == right) break :blk .eq;
            break :blk if (!left and right) .lt else .gt;
        },
        .number => |left| blk: {
            const right = rhs.number;
            if (left < right) break :blk .lt;
            if (left > right) break :blk .gt;
            break :blk .eq;
        },
        .string => |left| compareTextOrderKeys(left, rhs.string, collation),
        .json => |left| switch (std.mem.order(u8, left, rhs.json)) {
            .lt => .lt,
            .eq => .eq,
            .gt => .gt,
        },
    };
}

fn compareTextOrderKeys(lhs: []const u8, rhs: []const u8, collation: ?[]const u8) ScalarComparison {
    return scalarComparisonFromTextComparison(relational_collation.compareTextForOrdering(lhs, rhs, collation));
}

fn textOrderKeysEqualWithCollation(lhs: []const u8, rhs: []const u8, collation: ?[]const u8) bool {
    return relational_collation.textEqual(lhs, rhs, collation);
}

fn scalarComparisonFromTextComparison(comparison: relational_collation.TextComparison) ScalarComparison {
    return switch (comparison) {
        .lt => .lt,
        .eq => .eq,
        .gt => .gt,
    };
}

pub fn queryOrderKeysEqual(lhs: []const QueryOrderKey, rhs: []const QueryOrderKey) bool {
    return queryOrderKeysEqualWithCollation(&.{}, lhs, rhs);
}

fn queryOrderKeysEqualWithCollation(
    order_by: []const types.RelationalRowsQueryOrder,
    lhs: []const QueryOrderKey,
    rhs: []const QueryOrderKey,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs, 0..) |left, right, i| {
        const collation = if (i < order_by.len) order_by[i].collation else null;
        if (!queryOrderKeyEqualWithCollation(left, right, collation)) return false;
    }
    return true;
}

fn queryOrderKeyEqualWithCollation(lhs: QueryOrderKey, rhs: QueryOrderKey, collation: ?[]const u8) bool {
    const left_rank = queryOrderKeyRank(lhs);
    const right_rank = queryOrderKeyRank(rhs);
    if (left_rank != right_rank) return false;
    return switch (lhs) {
        .missing, .null => true,
        .bool => |left| left == rhs.bool,
        .number => |left| left == rhs.number,
        .string => |left| textOrderKeysEqualWithCollation(left, rhs.string, collation),
        .json => |left| std.mem.eql(u8, left, rhs.json),
    };
}

pub fn queryOrderedCandidatesLessThan(
    order_by: []const types.RelationalRowsQueryOrder,
    lhs_order_keys: []const QueryOrderKey,
    lhs_ordinal: usize,
    rhs_order_keys: []const QueryOrderKey,
    rhs_ordinal: usize,
) bool {
    for (order_by, 0..) |order, i| {
        const comparison = compareQueryOrderKeysWithCollation(lhs_order_keys[i], rhs_order_keys[i], order.collation);
        if (comparison == .eq) continue;
        return switch (order.direction) {
            .asc => comparison == .lt,
            .desc => comparison == .gt,
        };
    }
    return lhs_ordinal < rhs_ordinal;
}

test "relational rows text order keys honor resolved case-insensitive collation" {
    try std.testing.expectEqual(ScalarComparison.lt, compareQueryOrderKeysWithCollation(.{ .string = "Beta" }, .{ .string = "alpha" }, null));
    try std.testing.expectEqual(ScalarComparison.gt, compareQueryOrderKeysWithCollation(.{ .string = "Beta" }, .{ .string = "alpha" }, "antfly.case_insensitive"));
    try std.testing.expectEqual(ScalarComparison.lt, compareQueryOrderKeysWithCollation(.{ .string = "ALPHA" }, .{ .string = "alpha" }, "antfly.case_insensitive"));

    const order_by = [_]types.RelationalRowsQueryOrder{.{
        .field = "name",
        .collation = "antfly.case_insensitive",
    }};
    const left_keys = [_]QueryOrderKey{.{ .string = "Beta" }};
    const right_keys = [_]QueryOrderKey{.{ .string = "alpha" }};
    try std.testing.expect(!queryOrderedCandidatesLessThan(order_by[0..], left_keys[0..], 0, right_keys[0..], 1));
    try std.testing.expect(queryOrderedCandidatesLessThan(order_by[0..], right_keys[0..], 1, left_keys[0..], 0));
}

test "relational rows scalar predicates honor case-insensitive collation" {
    const alloc = std.testing.allocator;
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, "{\"name\":\"Beta\"}", .{});
    defer parsed.deinit();

    try std.testing.expect(!try queryPredicatePasses(alloc, parsed.value, .{
        .name = "",
        .field = "name",
        .op = .eq,
        .value_json = "\"beta\"",
    }));
    try std.testing.expect(try queryPredicatePasses(alloc, parsed.value, .{
        .name = "",
        .field = "name",
        .op = .eq,
        .value_json = "\"beta\"",
        .collation = "antfly.case_insensitive",
    }));
    try std.testing.expect(try queryPredicatePasses(alloc, parsed.value, .{
        .name = "",
        .field = "name",
        .op = .is_not_distinct,
        .value_json = "\"beta\"",
        .collation = "antfly.case_insensitive",
    }));
}

test "relational rows grouped predicates resolve collation from columns" {
    const alloc = std.testing.allocator;
    const columns = [_]schema_mod.RelationalColumn{.{
        .name = "state",
        .path = "state",
        .field_type = .keyword,
        .collation = "antfly.case_insensitive",
    }};
    const source_predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "state",
        .op = .eq,
        .value_json = "\"source\"",
    }};
    const grouped_predicates = [_]types.RelationalRowsPredicateGroup{.{
        .predicates = source_predicates[0..],
    }};
    const access_grouped_predicates = [_]types.RelationalRowsAccessPredicateGroup{.{
        .predicates = source_predicates[0..],
    }};

    try std.testing.expect(try queryJsonMatchesRequestWithColumns(alloc, "{\"state\":\"SOURCE\"}", .{
        .predicates = source_predicates[0..],
    }, columns[0..], 0));
    try std.testing.expect(try queryJsonMatchesRequestWithColumns(alloc, "{\"state\":\"SOURCE\"}", .{
        .or_predicates = grouped_predicates[0..],
    }, columns[0..], 0));
    try std.testing.expect(!try queryJsonMatchesRequestWithColumns(alloc, "{\"state\":\"SOURCE\"}", .{
        .not_predicates = grouped_predicates[0..],
    }, columns[0..], 0));
    try std.testing.expect(try queryJsonMatchesRequestWithColumns(alloc, "{\"state\":\"SOURCE\"}", .{
        .access_or_predicates = access_grouped_predicates[0..],
    }, columns[0..], 0));
    try std.testing.expect(!try queryJsonMatchesRequestWithColumns(alloc, "{\"state\":\"SOURCE\"}", .{
        .access_not_predicates = access_grouped_predicates[0..],
    }, columns[0..], 0));
}

fn queryOrderKeyRank(key: QueryOrderKey) u8 {
    return switch (key) {
        .bool => 0,
        .number => 1,
        .string => 2,
        .json => 3,
        .null => 4,
        .missing => 5,
    };
}

pub const MutationSourceCandidate = struct {
    doc_key: []u8,
    json: []u8,
    version: u64 = 0,
    order_keys: []QueryOrderKey = &.{},
    ordinal: usize,
    group_id: u64 = 0,

    pub fn deinit(self: *@This(), alloc: Allocator) void {
        alloc.free(self.doc_key);
        alloc.free(self.json);
        freeQueryOrderKeySlice(alloc, self.order_keys);
        self.* = undefined;
    }
};

pub fn cloneMutationSourceCandidateAlloc(
    alloc: Allocator,
    candidate: MutationSourceCandidate,
) !MutationSourceCandidate {
    const doc_key = try alloc.dupe(u8, candidate.doc_key);
    errdefer alloc.free(doc_key);
    const json = try alloc.dupe(u8, candidate.json);
    errdefer alloc.free(json);
    const order_keys = try cloneQueryOrderKeysAlloc(alloc, candidate.order_keys);
    errdefer freeQueryOrderKeySlice(alloc, order_keys);
    return .{
        .doc_key = doc_key,
        .json = json,
        .version = candidate.version,
        .order_keys = order_keys,
        .ordinal = candidate.ordinal,
        .group_id = candidate.group_id,
    };
}

pub fn cloneMutationParticipantPredicatesAlloc(
    alloc: Allocator,
    predicates: []const types.TransactionVersionPredicate,
) ![]types.TransactionVersionPredicate {
    if (predicates.len == 0) return &.{};
    var out = try alloc.alloc(types.TransactionVersionPredicate, predicates.len);
    var count: usize = 0;
    errdefer {
        for (out[0..count]) |predicate| alloc.free(@constCast(predicate.key));
        alloc.free(out);
    }
    for (predicates) |predicate| {
        out[count] = .{
            .key = try alloc.dupe(u8, predicate.key),
            .expected_version = predicate.expected_version,
        };
        count += 1;
    }
    return out;
}

pub fn freeMutationParticipantPredicates(
    alloc: Allocator,
    predicates: []types.TransactionVersionPredicate,
) void {
    for (predicates) |predicate| alloc.free(@constCast(predicate.key));
    if (predicates.len > 0) alloc.free(predicates);
}

pub fn cloneMutationParticipantWritesAlloc(
    alloc: Allocator,
