fn appendGraphTableFunctionTailJson(
    writer: *std.Io.Writer,
    graph_name: []const u8,
    node: ?graph_query_mod.GraphResultNode,
    match_json: ?[]const u8,
    stored_json: ?[]const u8,
    alias_projections: []const types.RelationalRowsGraphAliasProjection,
    match: ?types.GraphPatternMatch,
) !void {
    try writer.writeAll(",\"graph_name\":");
    try std.json.Stringify.value(.{ .string = graph_name }, .{}, writer);
    try writer.writeAll(",\"node_key\":");
    if (node) |value| {
        try std.json.Stringify.value(.{ .string = value.key }, .{}, writer);
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll(",\"depth\":");
    if (node) |value| {
        try writer.print("{d}", .{value.depth});
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll(",\"distance\":");
    if (node) |value| {
        try writer.print("{d}", .{value.distance});
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll(",\"path_json\":");
    if (node) |value| {
        try graphPathJson(value.path, value.path_edges, writer);
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll(",\"match_json\":");
    if (match_json) |json| try writer.writeAll(json) else try writer.writeAll("null");
    try writer.writeAll(",\"stored_json\":");
    if (stored_json) |json| try writer.writeAll(json) else try writer.writeAll("null");
    try appendGraphAliasProjectionFieldsJson(writer, alias_projections, match);
    try writer.writeAll("}");
}

fn appendGraphAliasProjectionFieldsJson(
    writer: *std.Io.Writer,
    alias_projections: []const types.RelationalRowsGraphAliasProjection,
    match: ?types.GraphPatternMatch,
) !void {
    for (alias_projections) |projection| {
        try writer.writeAll(",");
        try std.json.Stringify.value(.{ .string = projection.output }, .{}, writer);
        try writer.writeAll(":");
        const binding = if (match) |value| graphPatternBindingForAlias(value, projection.alias) else null;
        if (binding) |value| {
            try writeGraphAliasProjectionValueJson(writer, projection.field, value.node);
        } else {
            try writer.writeAll("null");
        }
    }
}

fn graphPatternBindingForAlias(
    match: types.GraphPatternMatch,
    alias: []const u8,
) ?types.GraphPatternBinding {
    for (match.bindings) |binding| {
        if (std.mem.eql(u8, binding.alias, alias)) return binding;
    }
    return null;
}

fn writeGraphAliasProjectionValueJson(
    writer: *std.Io.Writer,
    field: []const u8,
    node: graph_query_mod.GraphResultNode,
) !void {
    if (std.mem.eql(u8, field, "key")) {
        try std.json.Stringify.value(.{ .string = node.key }, .{}, writer);
    } else if (std.mem.eql(u8, field, "depth")) {
        try writer.print("{d}", .{node.depth});
    } else if (std.mem.eql(u8, field, "distance")) {
        try writer.print("{d}", .{node.distance});
    } else {
        try writer.writeAll("null");
    }
}

fn graphPathJson(
    path: ?[]const []const u8,
    path_edges: ?[]const graph_query_mod.PathEdgeInfo,
    writer: *std.Io.Writer,
) !void {
    try writer.writeAll("{\"nodes\":");
    if (path) |nodes| {
        try writer.writeAll("[");
        for (nodes, 0..) |node, i| {
            if (i > 0) try writer.writeAll(",");
            try std.json.Stringify.value(.{ .string = node }, .{}, writer);
        }
        try writer.writeAll("]");
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll(",\"edges\":");
    if (path_edges) |edges| {
        try writer.writeAll("[");
        for (edges, 0..) |edge, i| {
            if (i > 0) try writer.writeAll(",");
            try writer.writeAll("{\"source\":");
            try std.json.Stringify.value(.{ .string = edge.source }, .{}, writer);
            try writer.writeAll(",\"target\":");
            try std.json.Stringify.value(.{ .string = edge.target }, .{}, writer);
            try writer.writeAll(",\"type\":");
            try std.json.Stringify.value(.{ .string = edge.edge_type }, .{}, writer);
            try writer.print(",\"weight\":{d}", .{edge.weight});
            if (edge.metadata.len > 0) {
                try writer.writeAll(",\"metadata\":");
                try writer.writeAll(edge.metadata);
            }
            try writer.writeAll("}");
        }
        try writer.writeAll("]");
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll("}");
}

pub fn graphPatternMatchJsonAlloc(alloc: Allocator, match: types.GraphPatternMatch) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeAll("{\"bindings\":[");
    for (match.bindings, 0..) |binding, i| {
        if (i > 0) try writer.writeAll(",");
        try writer.writeAll("{\"alias\":");
        try std.json.Stringify.value(.{ .string = binding.alias }, .{}, writer);
        try writer.writeAll(",\"node\":");
        try graphNodeJson(binding.node, writer);
        try writer.writeAll("}");
    }
    try writer.writeAll("],\"path\":[");
    for (match.path, 0..) |edge, i| {
        if (i > 0) try writer.writeAll(",");
        try writer.writeAll("{\"source\":");
        try std.json.Stringify.value(.{ .string = edge.source }, .{}, writer);
        try writer.writeAll(",\"target\":");
        try std.json.Stringify.value(.{ .string = edge.target }, .{}, writer);
        try writer.writeAll(",\"type\":");
        try std.json.Stringify.value(.{ .string = edge.edge_type }, .{}, writer);
        try writer.print(",\"weight\":{d}}}", .{edge.weight});
    }
    try writer.writeAll("]}");
    return try out.toOwnedSlice();
}

fn graphNodeJson(node: graph_query_mod.GraphResultNode, writer: *std.Io.Writer) !void {
    try writer.writeAll("{\"key\":");
    try std.json.Stringify.value(.{ .string = node.key }, .{}, writer);
    try writer.print(",\"depth\":{d},\"distance\":{d}", .{ node.depth, node.distance });
    try writer.writeAll(",\"path\":");
    try graphPathJson(node.path, node.path_edges, writer);
    try writer.writeAll("}");
}

test "relational graph table function match rows expose alias projection fields" {
    const alloc = std.testing.allocator;

    var bindings = try alloc.alloc(types.GraphPatternBinding, 2);
    var match = types.GraphPatternMatch{
        .bindings = bindings,
        .path = &.{},
    };
    defer match.deinit(alloc);
    bindings[0] = .{
        .alias = try alloc.dupe(u8, "doc"),
        .node = .{
            .key = try alloc.dupe(u8, "doc:root"),
            .depth = 0,
            .distance = 0.0,
            .path = null,
            .path_edges = null,
        },
    };
    bindings[1] = .{
        .alias = try alloc.dupe(u8, "target"),
        .node = .{
            .key = try alloc.dupe(u8, "doc:leaf"),
            .depth = 1,
            .distance = 1.0,
            .path = null,
            .path_edges = null,
        },
    };

    const alias_projections = [_]types.RelationalRowsGraphAliasProjection{
        .{ .alias = "doc", .field = "key", .output = "doc_key" },
        .{ .alias = "target", .field = "key", .output = "target_key" },
        .{ .alias = "target", .field = "depth", .output = "target_depth" },
    };
    const match_json = try graphPatternMatchJsonAlloc(alloc, match);
    defer alloc.free(match_json);
    const row = try graphTableFunctionPatternMatchRowJsonAlloc(alloc, "graph_match", match, match_json, alias_projections[0..]);
    defer alloc.free(row);

    try std.testing.expect(std.mem.indexOf(u8, row, "\"doc_key\":\"doc:root\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, row, "\"target_key\":\"doc:leaf\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, row, "\"target_depth\":1") != null);
    try std.testing.expect(std.mem.indexOf(u8, row, "\"match_json\":") != null);
}

pub const system_versioned_history_prefix = "\x00\x00__metadata__:relational-system-history:v1:";
pub const system_versioned_history_retention_key = "\x00\x00__metadata__:relational-system-history-retention:v1";

pub const SystemVersionedHistoryRetention = struct {
    min_commit_sequence: u64 = 0,
    min_transaction_time_ns: u64 = 0,
};

pub fn systemVersionedHistoryPrefixForDocKeyAlloc(alloc: Allocator, doc_key: []const u8) ![]u8 {
    const encoded_len = std.base64.url_safe_no_pad.Encoder.calcSize(doc_key.len);
    const out = try alloc.alloc(u8, system_versioned_history_prefix.len + encoded_len + 1);
    @memcpy(out[0..system_versioned_history_prefix.len], system_versioned_history_prefix);
    _ = std.base64.url_safe_no_pad.Encoder.encode(out[system_versioned_history_prefix.len..][0..encoded_len], doc_key);
    out[out.len - 1] = ':';
    return out;
}

pub fn systemVersionedHistoryKeyAlloc(alloc: Allocator, doc_key: []const u8, sequence: u64, ordinal: u32) ![]u8 {
    const prefix = try systemVersionedHistoryPrefixForDocKeyAlloc(alloc, doc_key);
    defer alloc.free(prefix);
    const out = try alloc.alloc(u8, prefix.len + 16 + 1 + 8);
    @memcpy(out[0..prefix.len], prefix);
    appendFixedHexU64(out[prefix.len..][0..16], sequence);
    out[prefix.len + 16] = ':';
    appendFixedHexU32(out[prefix.len + 17 ..][0..8], ordinal);
    return out;
}

pub fn systemVersionedHistoryJsonValueAlloc(
    alloc: Allocator,
    value: []const u8,
) ![]u8 {
    if (value.len > 0 and value[0] == '{') return try alloc.dupe(u8, value);
    return try mapper.materializeRelationalRowValueAlloc(alloc, value);
}

pub fn systemVersionedHistoryRetentionValueAlloc(
    alloc: Allocator,
    retention: SystemVersionedHistoryRetention,
) ![]u8 {
    return try std.json.Stringify.valueAlloc(alloc, .{
        .version = @as(u32, 1),
        .min_commit_sequence = retention.min_commit_sequence,
        .min_transaction_time_ns = retention.min_transaction_time_ns,
    }, .{});
}

pub fn appendSystemVersionedHistoryRecord(
    alloc: Allocator,
    doc_key: []const u8,
    new_doc_key: ?[]const u8,
    operation: []const u8,
    before_json: ?[]const u8,
    after_json: ?[]const u8,
    sequence: u64,
    timestamp_ns: u64,
    ordinal: *u32,
    writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
    owned_keys: *std.ArrayListUnmanaged([]u8),
    owned_values: *std.ArrayListUnmanaged([]u8),
) !void {
    const key = try systemVersionedHistoryKeyAlloc(alloc, doc_key, sequence, ordinal.*);
    var key_owned = true;
    errdefer if (key_owned) alloc.free(key);
    ordinal.* += 1;

    const value = try std.json.Stringify.valueAlloc(alloc, .{
        .version = @as(u32, 1),
        .operation = operation,
        .doc_key = doc_key,
        .new_doc_key = new_doc_key,
        .commit_sequence = sequence,
        .transaction_time_ns = timestamp_ns,
        .before_json = before_json,
        .after_json = after_json,
    }, .{ .emit_null_optional_fields = false });
    var value_owned = true;
    errdefer if (value_owned) alloc.free(value);

    try owned_keys.append(alloc, key);
    key_owned = false;
    try owned_values.append(alloc, value);
    value_owned = false;
    try writes.append(alloc, .{ .key = key, .value = value });
}

fn appendFixedHexU64(out: []u8, value: u64) void {
    const hex = "0123456789abcdef";
    var shift: u6 = 60;
    for (out[0..16]) |*byte| {
        byte.* = hex[@as(usize, @intCast((value >> shift) & 0x0f))];
        if (shift == 0) break;
        shift -= 4;
    }
}

fn appendFixedHexU32(out: []u8, value: u32) void {
    const hex = "0123456789abcdef";
    var shift: u5 = 28;
    for (out[0..8]) |*byte| {
        byte.* = hex[@as(usize, @intCast((value >> shift) & 0x0f))];
        if (shift == 0) break;
        shift -= 4;
    }
}

