pub fn validateAggregateAgainstCteOutput(
    materialized_ctes: []MaterializedCte,
    req: types.RelationalRowsAggregateRequest,
) !void {
    const source_output = sourceCteOutputFields(materialized_ctes, req.source) orelse return;
    try validateAggregateAgainstOutputFields(source_output, req);
}

pub fn validateAggregateAgainstOutputFields(
    source_output: []const []const u8,
    req: types.RelationalRowsAggregateRequest,
) !void {
    for (req.group_by) |field| try validateOutputField(source_output, field);
    for (req.group_expressions) |projection| try validateExpressionAgainstCteOutput(source_output, projection.expression);
    for (req.aggregations) |aggregation| {
        if (aggregation.field) |field| try validateOutputField(source_output, field);
        if (aggregation.expression) |expression| try validateExpressionAgainstCteOutput(source_output, expression);
        for (aggregation.array_order_by) |order| try validateQueryOrderAgainstCteOutput(source_output, order);
        for (aggregation.filter_predicates) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_array_any) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_array_contains) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_array_eq) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_in_predicates) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_json_contains) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_json_path_eq) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_json_path_exists) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_text_patterns) |predicate| try validateOutputField(source_output, predicate.field);
        for (aggregation.filter_expressions) |condition| try validateExpressionConditionAgainstCteOutput(source_output, condition);
        for (aggregation.filter_expression_array_contains) |predicate| try validateExpressionAgainstCteOutput(source_output, predicate.expression);
        for (aggregation.filter_any) |group| {
            for (group.conditions) |condition| try validateExpressionConditionAgainstCteOutput(source_output, condition);
        }
        for (aggregation.filter_not) |group| {
            for (group.conditions) |condition| try validateExpressionConditionAgainstCteOutput(source_output, condition);
        }
    }
}

pub fn validateWindowAgainstCteOutput(
    materialized_ctes: []MaterializedCte,
    req: types.RelationalRowsWindowRequest,
) !void {
    const source_output = sourceCteOutputFields(materialized_ctes, req.source) orelse return;
    try validateWindowAgainstOutputFields(source_output, req);
}

pub fn validateWindowAgainstOutputFields(
    source_output: []const []const u8,
    req: types.RelationalRowsWindowRequest,
) !void {
    for (req.windows) |window| {
        for (window.partition_by) |field| try validateOutputField(source_output, field);
        for (window.order_by) |order| try validateQueryOrderAgainstCteOutput(source_output, order);
        if (window.value_expression) |expression| try validateExpressionAgainstCteOutput(source_output, expression);
        for (window.filter_predicates) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_array_any) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_array_contains) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_array_eq) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_in_predicates) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_json_contains) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_json_path_eq) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_json_path_exists) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_text_patterns) |predicate| try validateOutputField(source_output, predicate.field);
        for (window.filter_expressions) |condition| try validateExpressionConditionAgainstCteOutput(source_output, condition);
        for (window.filter_expression_array_contains) |predicate| try validateExpressionAgainstCteOutput(source_output, predicate.expression);
        for (window.filter_any) |group| {
            for (group.conditions) |condition| try validateExpressionConditionAgainstCteOutput(source_output, condition);
        }
        for (window.filter_not) |group| {
            for (group.conditions) |condition| try validateExpressionConditionAgainstCteOutput(source_output, condition);
        }
    }
    if (!req.select_all) {
        for (req.select) |field| try validateOutputField(source_output, field);
    }
}

pub fn validateJoinAgainstCteOutput(
    materialized_ctes: []MaterializedCte,
    req: types.RelationalRowsJoinRequest,
) !void {
    const left_output = sourceCteOutputFields(materialized_ctes, req.left);
    const right_output = sourceCteOutputFields(materialized_ctes, req.right);
    try validateJoinAgainstOutputFields(left_output, right_output, req);
}

pub fn validateJoinAgainstOutputFields(
    left_output: ?[]const []const u8,
    right_output: ?[]const []const u8,
    req: types.RelationalRowsJoinRequest,
) !void {
    if (left_output) |fields| try validateQueryAgainstCteOutput(joinSideSource(req.left), fields);
    if (right_output) |fields| try validateQueryAgainstCteOutput(joinSideSource(req.right), fields);
    for (req.on) |join_on| {
        if (left_output) |fields| try validateOutputField(fields, join_on.left_field);
        if (right_output) |fields| try validateOutputField(fields, join_on.right_field);
    }
    for (req.select) |projection| switch (projection.side) {
        .left => if (left_output) |fields| try validateOutputField(fields, projection.field),
        .right => if (right_output) |fields| try validateOutputField(fields, projection.field),
    };
    try validateJoinMatchExpressionsAgainstOutputFields(left_output, right_output, req.on_expression_predicates, req.on_expression_or_predicates, req.on_expression_not_predicates, req.on_expression_array_contains);
    try validateJoinMatchExpressionsAgainstOutputFields(left_output, right_output, req.match_expression_predicates, req.match_expression_or_predicates, req.match_expression_not_predicates, req.match_expression_array_contains);
}

pub fn validateLateralAgainstCteOutput(
    materialized_ctes: []MaterializedCte,
    req: types.RelationalRowsLateralRequest,
) !void {
    const left_output = sourceCteOutputFields(materialized_ctes, req.left);
    const right_output = sourceCteOutputFields(materialized_ctes, req.right);
    try validateLateralAgainstOutputFields(left_output, right_output, req);
}

pub fn validateLateralAgainstOutputFields(
    left_output: ?[]const []const u8,
    right_output: ?[]const []const u8,
    req: types.RelationalRowsLateralRequest,
) !void {
    if (left_output) |fields| try validateQueryAgainstCteOutput(joinSideSource(req.left), fields);
    if (right_output) |fields| try validateQueryAgainstCteOutput(joinSideSource(req.right), fields);
    for (req.correlations) |correlation| {
        if (left_output) |fields| try validateOutputField(fields, correlation.left_field);
        if (right_output) |fields| try validateOutputField(fields, correlation.right_field);
    }
    for (req.select) |projection| switch (projection.side) {
        .left => if (left_output) |fields| try validateOutputField(fields, projection.field),
        .right => if (right_output) |fields| try validateOutputField(fields, projection.field),
    };
    try validateJoinMatchExpressionsAgainstOutputFields(left_output, right_output, req.match_expression_predicates, req.match_expression_or_predicates, req.match_expression_not_predicates, req.match_expression_array_contains);
}

fn validateJoinMatchExpressionsAgainstOutputFields(
    left_output: ?[]const []const u8,
    right_output: ?[]const []const u8,
    predicates: []const types.RelationalRowsExpressionCondition,
    any_groups: []const types.RelationalRowsExpressionPredicateGroup,
    not_groups: []const types.RelationalRowsExpressionPredicateGroup,
    array_contains: []const types.RelationalRowsExpressionArrayContainsPredicate,
) !void {
    for (predicates) |condition| try validateJoinMatchExpressionConditionAgainstOutputFields(left_output, right_output, condition);
    for (any_groups) |group| {
        for (group.conditions) |condition| try validateJoinMatchExpressionConditionAgainstOutputFields(left_output, right_output, condition);
    }
    for (not_groups) |group| {
        for (group.conditions) |condition| try validateJoinMatchExpressionConditionAgainstOutputFields(left_output, right_output, condition);
    }
    for (array_contains) |predicate| try validateJoinMatchExpressionAgainstOutputFields(left_output, right_output, predicate.expression);
}

fn validateJoinMatchExpressionConditionAgainstOutputFields(
    left_output: ?[]const []const u8,
    right_output: ?[]const []const u8,
    condition: types.RelationalRowsExpressionCondition,
) anyerror!void {
    try validateJoinMatchExpressionAgainstOutputFields(left_output, right_output, condition.lhs);
    for (condition.rhs) |expression| try validateJoinMatchExpressionAgainstOutputFields(left_output, right_output, expression);
}

fn validateJoinMatchExpressionAgainstOutputFields(
    left_output: ?[]const []const u8,
    right_output: ?[]const []const u8,
    expression: types.RelationalRowsExpression,
) anyerror!void {
    if (expression.kind == .field) {
        switch (expression.field_source) {
            .source => if (right_output) |fields| try validateOutputField(fields, expression.field),
            .row => if (left_output) |fields| try validateOutputField(fields, expression.field),
            .existing, .proposed => return error.InvalidQueryRequest,
        }
    }
    for (expression.operands) |operand| try validateJoinMatchExpressionAgainstOutputFields(left_output, right_output, operand);
    for (expression.case_branches) |branch| {
        try validateJoinMatchExpressionConditionAgainstOutputFields(left_output, right_output, branch.when);
        try validateJoinMatchExpressionAgainstOutputFields(left_output, right_output, branch.then);
    }
    for (expression.case_else) |fallback| try validateJoinMatchExpressionAgainstOutputFields(left_output, right_output, fallback);
}

fn fullRowSourceQuery(source_req: types.RelationalRowsQueryRequest) types.RelationalRowsQueryRequest {
    var source = source_req;
    source.select = &.{};
    source.json_extract = &.{};
    source.array_length = &.{};
    source.coalesce = &.{};
    source.field_aliases = &.{};
    source.expressions = &.{};
    source.select_all = true;
    return source;
}

pub fn joinSideSource(source_req: types.RelationalRowsQueryRequest) types.RelationalRowsQueryRequest {
    return fullRowSourceQuery(source_req);
}

pub fn lateralLeftSource(source_req: types.RelationalRowsQueryRequest) types.RelationalRowsQueryRequest {
    return joinSideSource(source_req);
}

pub fn aggregateSourceQuery(req: types.RelationalRowsAggregateRequest) types.RelationalRowsQueryRequest {
    var source = fullRowSourceQuery(req.source);
    source.order_by = &.{};
    source.limit = null;
    source.offset = 0;
    return source;
}

pub fn windowSourceQuery(
    req: types.RelationalRowsWindowRequest,
    source_order: []const types.RelationalRowsQueryOrder,
) types.RelationalRowsQueryRequest {
    var source = fullRowSourceQuery(req.source);
    source.order_by = source_order;
    source.limit = null;
    source.offset = 0;
    source.row_claim = null;
    return source;
}

pub fn joinedMutationTargetQuery(req: types.RelationalRowsJoinedMutationSourceRequest) types.RelationalRowsQueryRequest {
    return switch (req.target_side) {
        .left => req.join.left,
        .right => req.join.right,
    };
}

pub fn joinedMutationSourceQuery(req: types.RelationalRowsJoinedMutationSourceRequest) types.RelationalRowsQueryRequest {
    return switch (req.target_side) {
        .left => req.join.right,
        .right => req.join.left,
    };
}

pub fn joinedMutationTargetSource(req: types.RelationalRowsJoinedMutationSourceRequest) types.RelationalRowsQueryRequest {
    var source = fullRowSourceQuery(joinedMutationTargetQuery(req));
    source.row_claim = null;
    source.limit = null;
    source.offset = 0;
    return source;
}

pub fn joinedMutationSourceSide(req: types.RelationalRowsJoinedMutationSourceRequest) types.RelationalRowsQueryRequest {
    var source = fullRowSourceQuery(joinedMutationSourceQuery(req));
    source.row_claim = null;
    return source;
}

pub fn joinedMutationClaim(req: types.RelationalRowsJoinedMutationSourceRequest) ?types.RowClaimRequest {
    return joinedMutationTargetQuery(req).row_claim;
}

pub fn joinedMutationTargetJoinSide(req: types.RelationalRowsJoinedMutationSourceRequest) JoinSide {
    return switch (req.target_side) {
        .left => .left,
        .right => .right,
    };
}

pub fn joinedMutationSourceJoinSide(req: types.RelationalRowsJoinedMutationSourceRequest) JoinSide {
    return switch (req.target_side) {
        .left => .right,
        .right => .left,
    };
}

pub fn buildJoinedMutationSourceCandidatesFromCollectedRowsAlloc(
    alloc: Allocator,
    req: types.RelationalRowsJoinedMutationSourceRequest,
    target_candidates: *[]MutationSourceCandidate,
    source_rows: []const []const u8,
    now_ns: u64,
) ![]JoinedMutationSourceCandidate {
    return try buildJoinedMutationSourceCandidatesFromCollectedRowsWithColumnsAlloc(alloc, req, target_candidates, &.{}, source_rows, &.{}, now_ns);
}

pub fn buildJoinedMutationSourceCandidatesFromCollectedRowsWithColumnsAlloc(
    alloc: Allocator,
    req: types.RelationalRowsJoinedMutationSourceRequest,
    target_candidates: *[]MutationSourceCandidate,
    target_columns: []const schema_mod.RelationalColumn,
    source_rows: []const []const u8,
    source_columns: []const schema_mod.RelationalColumn,
    now_ns: u64,
) ![]JoinedMutationSourceCandidate {
    var source_index = std.StringArrayHashMapUnmanaged(JoinRightList).empty;
    defer deinitJoinRightIndex(alloc, &source_index);
    const source_join_side = joinedMutationSourceJoinSide(req);
    for (source_rows, 0..) |source_row, source_index_id| {
        var parsed_source = std.json.parseFromSlice(std.json.Value, alloc, source_row, .{}) catch return error.InvalidQueryRequest;
        defer parsed_source.deinit();
        if (parsed_source.value != .object) return error.InvalidQueryRequest;
        const key_json = (try joinKeyJsonAlloc(alloc, parsed_source.value, req.join.on, source_join_side)) orelse continue;
        var key_transferred = false;
        errdefer if (!key_transferred) alloc.free(key_json);
        const gop = try source_index.getOrPut(alloc, key_json);
        if (!gop.found_existing) {
            gop.key_ptr.* = key_json;
            key_transferred = true;
            gop.value_ptr.* = .{};
        }
        try gop.value_ptr.indexes.append(alloc, source_index_id);
        if (gop.found_existing) alloc.free(key_json);
    }

    var candidates = std.ArrayListUnmanaged(JoinedMutationSourceCandidate).empty;
    errdefer {
        for (candidates.items) |*candidate| candidate.deinit(alloc);
        candidates.deinit(alloc);
    }
    const target_join_side = joinedMutationTargetJoinSide(req);
    for (target_candidates.*) |*target_row| {
        var parsed_target = std.json.parseFromSlice(std.json.Value, alloc, target_row.json, .{}) catch return error.InvalidQueryRequest;
        defer parsed_target.deinit();
        if (parsed_target.value != .object) return error.InvalidQueryRequest;
        const key_json = try joinKeyJsonAlloc(alloc, parsed_target.value, req.join.on, target_join_side);
        defer if (key_json) |key| alloc.free(key);
        const key = key_json orelse continue;
        const source_list = source_index.get(key) orelse continue;
        if (source_list.indexes.items.len != 1) return error.UnsupportedQueryRequest;
        if (!(try joinedMutationMatchPredicatesPassWithColumns(
            alloc,
            parsed_target.value,
            target_columns,
            source_rows[source_list.indexes.items[0]],
            source_columns,
            req,
            now_ns,
        ))) continue;
        const source_json = try alloc.dupe(u8, source_rows[source_list.indexes.items[0]]);
        var source_transferred = false;
        errdefer if (!source_transferred) alloc.free(source_json);
        try candidates.append(alloc, .{
            .target = .{
                .doc_key = target_row.doc_key,
                .json = target_row.json,
                .version = target_row.version,
                .order_keys = target_row.order_keys,
                .ordinal = target_row.ordinal,
                .group_id = target_row.group_id,
            },
            .source_json = source_json,
        });
        target_row.doc_key = &.{};
        target_row.json = &.{};
        target_row.order_keys = &.{};
        source_transferred = true;
    }
    for (target_candidates.*) |*target_row| target_row.deinit(alloc);
    if (target_candidates.*.len > 0) alloc.free(target_candidates.*);
    target_candidates.* = @constCast((&[_]MutationSourceCandidate{})[0..]);
    return try candidates.toOwnedSlice(alloc);
}

fn joinedMutationMatchPredicatesPass(
    alloc: Allocator,
    target_row: std.json.Value,
    source_row_json: []const u8,
    req: types.RelationalRowsJoinedMutationSourceRequest,
    now_ns: u64,
) !bool {
    return try joinedMutationMatchPredicatesPassWithColumns(alloc, target_row, &.{}, source_row_json, &.{}, req, now_ns);
}

fn joinedMutationMatchPredicatesPassWithColumns(
    alloc: Allocator,
    target_row: std.json.Value,
    target_columns: []const schema_mod.RelationalColumn,
    source_row_json: []const u8,
    source_columns: []const schema_mod.RelationalColumn,
    req: types.RelationalRowsJoinedMutationSourceRequest,
    now_ns: u64,
) !bool {
    if (req.match_expression_predicates.len == 0 and
        req.match_expression_or_predicates.len == 0 and
        req.match_expression_not_predicates.len == 0 and
        req.match_expression_array_contains.len == 0)
    {
        return true;
    }

    var parsed_source = std.json.parseFromSlice(std.json.Value, alloc, source_row_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed_source.deinit();
    if (parsed_source.value != .object) return error.InvalidQueryRequest;
    for (req.match_expression_predicates) |condition| {
        if (!(try expressionConditionMatchesWithSourcesAndColumnSets(alloc, target_row, null, parsed_source.value, condition, target_columns, source_columns, now_ns))) return false;
    }
    if (!(try expressionOrPredicateGroupsPassWithSourcesAndColumnSets(alloc, target_row, null, parsed_source.value, req.match_expression_or_predicates, target_columns, source_columns, now_ns))) return false;
    if (!(try expressionNotPredicateGroupsPassWithSourcesAndColumnSets(alloc, target_row, null, parsed_source.value, req.match_expression_not_predicates, target_columns, source_columns, now_ns))) return false;
    for (req.match_expression_array_contains) |predicate| {
        if (!(try queryExpressionArrayContainsPredicatePassesWithSourcesAndColumnSets(alloc, target_row, null, parsed_source.value, predicate, target_columns, source_columns, now_ns))) return false;
    }
    return true;
}

pub fn joinHasMatchPredicates(req: types.RelationalRowsJoinRequest) bool {
    return req.match_expression_predicates.len != 0 or
        req.match_expression_or_predicates.len != 0 or
        req.match_expression_not_predicates.len != 0 or
        req.match_expression_array_contains.len != 0;
}

pub fn joinHasOnExpressionPredicates(req: types.RelationalRowsJoinRequest) bool {
    return req.on_expression_predicates.len != 0 or
        req.on_expression_or_predicates.len != 0 or
        req.on_expression_not_predicates.len != 0 or
        req.on_expression_array_contains.len != 0;
}

pub fn joinFromSourceRowsAlloc(
    alloc: Allocator,
    req: types.RelationalRowsJoinRequest,
    left_rows: []const []const u8,
    right_rows: []const []const u8,
    now_ns: u64,
) !types.RelationalRowsJoinResult {
    return try joinFromSourceRowsWithColumnsAlloc(alloc, req, left_rows, &.{}, right_rows, &.{}, now_ns);
}

pub fn joinFromSourceRowsWithColumnsAlloc(
    alloc: Allocator,
    req: types.RelationalRowsJoinRequest,
    left_rows: []const []const u8,
    left_columns: []const schema_mod.RelationalColumn,
    right_rows: []const []const u8,
    right_columns: []const schema_mod.RelationalColumn,
    now_ns: u64,
) !types.RelationalRowsJoinResult {
    if (req.left.doc_key_range != null or req.right.doc_key_range != null) return error.InvalidQueryRequest;
    const selection = types.relationalRowsSelectJoinStrategy(
        req,
        left_rows.len,
        right_rows.len,
        types.relationalRowsJoinInputsSortedOnJoinKeys(req),
    ) orelse return error.UnsupportedQueryRequest;
    if (req.on.len == 0) return try joinFromSourceRowsCrossAlloc(alloc, req, left_rows, left_columns, right_rows, right_columns, selection, now_ns);
    return switch (selection.selected) {
        .lookup, .hash => try joinFromSourceRowsHashAlloc(alloc, req, left_rows, left_columns, right_rows, right_columns, selection, now_ns),
        .merge => try joinFromSourceRowsMergeAlloc(alloc, req, left_rows, left_columns, right_rows, right_columns, selection, now_ns),
        .auto => unreachable,
    };
}

fn joinFromSourceRowsCrossAlloc(
    alloc: Allocator,
    req: types.RelationalRowsJoinRequest,
    left_rows: []const []const u8,
    left_columns: []const schema_mod.RelationalColumn,
    right_rows: []const []const u8,
    right_columns: []const schema_mod.RelationalColumn,
    strategy_selection: types.RelationalRowsJoinStrategySelection,
    now_ns: u64,
) !types.RelationalRowsJoinResult {
    if (req.join_type != .inner) return error.UnsupportedQueryRequest;
    var joined = JoinRowsAccumulator.init(req);
    errdefer joined.deinit(alloc);

    for (left_rows) |left_row| {
        var parsed_left = std.json.parseFromSlice(std.json.Value, alloc, left_row, .{}) catch return error.InvalidQueryRequest;
        defer parsed_left.deinit();
        if (parsed_left.value != .object) return error.InvalidQueryRequest;

        for (right_rows) |right_row| {
            if (!(try joinOnExpressionPredicatesPass(alloc, parsed_left.value, left_columns, right_row, right_columns, req, now_ns))) continue;
            if (!(try joinMatchPredicatesPass(alloc, parsed_left.value, left_columns, right_row, right_columns, req, now_ns))) continue;
            try joined.appendJoinedRowAlloc(alloc, left_row, right_row, req.select);
        }
    }

    return try joined.finalizeJoinResultAlloc(alloc, req.order_by, strategy_selection, now_ns);
}

fn joinFromSourceRowsHashAlloc(
    alloc: Allocator,
    req: types.RelationalRowsJoinRequest,
    left_rows: []const []const u8,
    left_columns: []const schema_mod.RelationalColumn,
    right_rows: []const []const u8,
    right_columns: []const schema_mod.RelationalColumn,
    strategy_selection: types.RelationalRowsJoinStrategySelection,
    now_ns: u64,
) !types.RelationalRowsJoinResult {
    var right_matched: []bool = &.{};
    if (req.join_type == .full) {
        right_matched = try alloc.alloc(bool, right_rows.len);
        @memset(right_matched, false);
    }
    defer if (right_matched.len > 0) alloc.free(right_matched);

    var right_index = std.StringArrayHashMapUnmanaged(JoinRightList).empty;
    defer deinitJoinRightIndex(alloc, &right_index);
    for (right_rows, 0..) |right_row, right_index_id| {
        var parsed_right = std.json.parseFromSlice(std.json.Value, alloc, right_row, .{}) catch return error.InvalidQueryRequest;
        defer parsed_right.deinit();
        if (parsed_right.value != .object) return error.InvalidQueryRequest;
        const key_json = (try joinKeyJsonAlloc(alloc, parsed_right.value, req.on, .right)) orelse continue;
        var key_transferred = false;
        errdefer if (!key_transferred) alloc.free(key_json);
        const gop = try right_index.getOrPut(alloc, key_json);
        if (!gop.found_existing) {
            gop.key_ptr.* = key_json;
            key_transferred = true;
            gop.value_ptr.* = .{};
        }
        try gop.value_ptr.indexes.append(alloc, right_index_id);
        if (gop.found_existing) alloc.free(key_json);
    }

    var joined = JoinRowsAccumulator.init(req);
    errdefer joined.deinit(alloc);
    for (left_rows) |left_row| {
        var parsed_left = std.json.parseFromSlice(std.json.Value, alloc, left_row, .{}) catch return error.InvalidQueryRequest;
        defer parsed_left.deinit();
        if (parsed_left.value != .object) return error.InvalidQueryRequest;

        const key_json = try joinKeyJsonAlloc(alloc, parsed_left.value, req.on, .left);
        defer if (key_json) |key| alloc.free(key);
        if (key_json) |key| {
            if (right_index.get(key)) |right_list| {
                var on_matched = false;
                for (right_list.indexes.items) |right_index_id| {
                    const right_row = right_rows[right_index_id];
                    if (!(try joinOnExpressionPredicatesPass(alloc, parsed_left.value, left_columns, right_row, right_columns, req, now_ns))) continue;
                    on_matched = true;
                    if (req.join_type == .full) right_matched[right_index_id] = true;
                    if (!(try joinMatchPredicatesPass(alloc, parsed_left.value, left_columns, right_row, right_columns, req, now_ns))) continue;
                    try joined.appendJoinedRowAlloc(alloc, left_row, right_row, req.select);
                }
                if (on_matched or (req.join_type != .left and req.join_type != .full) or joinHasMatchPredicates(req)) continue;
            }
        }
        if ((req.join_type == .left or req.join_type == .full) and !joinHasMatchPredicates(req)) {
            try joined.appendJoinedRowAlloc(alloc, left_row, null, req.select);
        }
    }
    if (req.join_type == .full and !joinHasMatchPredicates(req)) {
        for (right_rows, 0..) |right_row, right_index_id| {
            if (right_matched[right_index_id]) continue;
            try joined.appendJoinedRowAlloc(alloc, null, right_row, req.select);
        }
    }

    return try joined.finalizeJoinResultAlloc(alloc, req.order_by, strategy_selection, now_ns);
}

fn joinFromSourceRowsMergeAlloc(
    alloc: Allocator,
    req: types.RelationalRowsJoinRequest,
    left_rows: []const []const u8,
    left_columns: []const schema_mod.RelationalColumn,
    right_rows: []const []const u8,
    right_columns: []const schema_mod.RelationalColumn,
    strategy_selection: types.RelationalRowsJoinStrategySelection,
    now_ns: u64,
) !types.RelationalRowsJoinResult {
    var joined = JoinRowsAccumulator.init(req);
    errdefer joined.deinit(alloc);

    var left_index: usize = 0;
    var right_index: usize = 0;
    while (left_index < left_rows.len) {
        var left_key = try joinOrderKeysForRowAlloc(alloc, left_rows[left_index], req.on, .left, now_ns);
        defer left_key.deinit(alloc);
        if (left_key.keys.len == 0) {
            try appendLeftJoinUnmatchedIfNeededAlloc(alloc, &joined, req, left_rows[left_index]);
            left_index += 1;
            continue;
        }

        const left_group_start = left_index;
        var left_group_end = left_index + 1;
        while (left_group_end < left_rows.len) : (left_group_end += 1) {
            var next_left_key = try joinOrderKeysForRowAlloc(alloc, left_rows[left_group_end], req.on, .left, now_ns);
            defer next_left_key.deinit(alloc);
            if (next_left_key.keys.len == 0) break;
            if (compareJoinOrderKeys(left_key.keys, next_left_key.keys) != .eq) break;
        }

        while (right_index < right_rows.len) {
            var right_key = try joinOrderKeysForRowAlloc(alloc, right_rows[right_index], req.on, .right, now_ns);
            defer right_key.deinit(alloc);
            if (right_key.keys.len == 0) {
                right_index += 1;
                continue;
            }
            const comparison = compareJoinOrderKeys(right_key.keys, left_key.keys);
            if (comparison == .lt) {
                right_index += 1;
                continue;
            }
            break;
        }

        const right_group_start = right_index;
        var right_group_end = right_index;
        var has_equal_right_group = false;
        if (right_index < right_rows.len) {
            var right_key = try joinOrderKeysForRowAlloc(alloc, right_rows[right_index], req.on, .right, now_ns);
            defer right_key.deinit(alloc);
            if (right_key.keys.len != 0 and compareJoinOrderKeys(right_key.keys, left_key.keys) == .eq) {
                has_equal_right_group = true;
                right_group_end = right_index + 1;
                while (right_group_end < right_rows.len) : (right_group_end += 1) {
                    var next_right_key = try joinOrderKeysForRowAlloc(alloc, right_rows[right_group_end], req.on, .right, now_ns);
                    defer next_right_key.deinit(alloc);
                    if (next_right_key.keys.len == 0) break;
                    if (compareJoinOrderKeys(right_key.keys, next_right_key.keys) != .eq) break;
                }
            }
        }

        if (has_equal_right_group) {
            for (left_rows[left_group_start..left_group_end]) |left_row| {
                var parsed_left = std.json.parseFromSlice(std.json.Value, alloc, left_row, .{}) catch return error.InvalidQueryRequest;
                defer parsed_left.deinit();
                if (parsed_left.value != .object) return error.InvalidQueryRequest;

                var on_matched = false;
                for (right_rows[right_group_start..right_group_end]) |right_row| {
                    if (!(try joinOnExpressionPredicatesPass(alloc, parsed_left.value, left_columns, right_row, right_columns, req, now_ns))) continue;
                    on_matched = true;
                    if (!(try joinMatchPredicatesPass(alloc, parsed_left.value, left_columns, right_row, right_columns, req, now_ns))) continue;
                    try joined.appendJoinedRowAlloc(alloc, left_row, right_row, req.select);
                }
                if (!on_matched and req.join_type == .left and !joinHasMatchPredicates(req)) {
                    try joined.appendJoinedRowAlloc(alloc, left_row, null, req.select);
                }
            }
            right_index = right_group_end;
        } else {
            for (left_rows[left_group_start..left_group_end]) |left_row| {
                try appendLeftJoinUnmatchedIfNeededAlloc(alloc, &joined, req, left_row);
            }
        }

        left_index = left_group_end;
    }

    return try joined.finalizeJoinResultAlloc(alloc, req.order_by, strategy_selection, now_ns);
}

const JoinOrderKeySet = struct {
    keys: []QueryOrderKey = &.{},

    fn deinit(self: *@This(), alloc: Allocator) void {
        freeQueryOrderKeySlice(alloc, self.keys);
        self.* = undefined;
    }
};

fn joinOrderKeysForRowAlloc(
    alloc: Allocator,
    row_json: []const u8,
    predicates: []const types.RelationalRowsJoinOn,
    side: JoinSide,
    now_ns: u64,
) !JoinOrderKeySet {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidQueryRequest;
    const keys = try alloc.alloc(QueryOrderKey, predicates.len);
    var initialized: usize = 0;
    errdefer {
        freeQueryOrderKeys(alloc, keys[0..initialized]);
        alloc.free(keys);
    }
    for (predicates) |predicate| {
        const field = switch (side) {
            .left => predicate.left_field,
            .right => predicate.right_field,
        };
        keys[initialized] = try queryOrderKeyAlloc(alloc, parsed.value, .{ .field = field }, now_ns);
        if (keys[initialized] == .missing or keys[initialized] == .null) {
            freeQueryOrderKeys(alloc, keys[0 .. initialized + 1]);
            alloc.free(keys);
            return .{};
        }
        initialized += 1;
    }
    return .{ .keys = keys };
}

fn compareJoinOrderKeys(lhs: []const QueryOrderKey, rhs: []const QueryOrderKey) ScalarComparison {
    for (lhs, rhs) |left, right| {
        const comparison = compareQueryOrderKeys(left, right);
        if (comparison != .eq) return comparison;
    }
    return .eq;
}

fn appendLeftJoinUnmatchedIfNeededAlloc(
    alloc: Allocator,
    joined: *JoinRowsAccumulator,
    req: types.RelationalRowsJoinRequest,
    left_row: []const u8,
) !void {
    if (req.join_type != .left or joinHasMatchPredicates(req)) return;
    try joined.appendJoinedRowAlloc(alloc, left_row, null, req.select);
}

const JoinRowsAccumulator = struct {
    rows: std.ArrayListUnmanaged([]const u8) = .empty,
    total_rows: usize = 0,
    offset: usize = 0,
    limit: ?usize = null,
    materialize_all: bool = false,

    fn init(req: types.RelationalRowsJoinRequest) JoinRowsAccumulator {
        return .{
            .offset = req.offset,
            .limit = if (req.limit) |limit| limit else null,
            .materialize_all = req.order_by.len != 0,
        };
    }

    fn deinit(self: *JoinRowsAccumulator, alloc: Allocator) void {
        for (self.rows.items) |row| alloc.free(@constCast(row));
        self.rows.deinit(alloc);
        self.* = undefined;
    }

    fn shouldRetainNext(self: JoinRowsAccumulator) bool {
        if (self.materialize_all) return true;
        if (self.total_rows < self.offset) return false;
        if (self.limit) |limit| return self.total_rows - self.offset < limit;
        return true;
    }

    fn appendJoinedRowAlloc(
        self: *JoinRowsAccumulator,
        alloc: Allocator,
        left_row: ?[]const u8,
        right_row: ?[]const u8,
        select: []const types.RelationalRowsJoinProjection,
    ) !void {
        const retain = self.shouldRetainNext();
        self.total_rows += 1;
        if (!retain) return;

        const row_json = try joinedRowJsonAlloc(alloc, left_row, right_row, select);
        var row_transferred = false;
        errdefer if (!row_transferred) alloc.free(row_json);
        try self.rows.append(alloc, row_json);
        row_transferred = true;
    }

    fn finalizeJoinResultAlloc(
        self: *JoinRowsAccumulator,
        alloc: Allocator,
        order_by: []const types.RelationalRowsQueryOrder,
        strategy_selection: ?types.RelationalRowsJoinStrategySelection,
        now_ns: u64,
    ) !types.RelationalRowsJoinResult {
        const total_rows = std.math.cast(u32, self.total_rows) orelse return error.UnsupportedQueryRequest;
        if (!self.materialize_all) {
            return .{
                .rows = try self.rows.toOwnedSlice(alloc),
                .total_rows = total_rows,
                .strategy_selection = strategy_selection,
            };
        }

        try sortOutputRowsAlloc(alloc, self.rows.items, order_by, now_ns);

        const start = @min(self.offset, self.rows.items.len);
        const limited_len: usize = if (self.limit) |limit_value|
            @min(limit_value, self.rows.items.len - start)
        else
            self.rows.items.len - start;
        if (start > 0 or limited_len < self.rows.items.len) {
            const kept = try alloc.dupe([]const u8, self.rows.items[start .. start + limited_len]);
            for (self.rows.items[0..start]) |row| alloc.free(@constCast(row));
            for (self.rows.items[start + limited_len ..]) |row| alloc.free(@constCast(row));
            self.rows.deinit(alloc);
            return .{ .rows = kept, .total_rows = total_rows, .strategy_selection = strategy_selection };
        }

        return .{
            .rows = try self.rows.toOwnedSlice(alloc),
            .total_rows = total_rows,
            .strategy_selection = strategy_selection,
        };
    }
};

fn joinOnExpressionPredicatesPass(
    alloc: Allocator,
    left_row: std.json.Value,
    left_columns: []const schema_mod.RelationalColumn,
    right_row_json: []const u8,
    right_columns: []const schema_mod.RelationalColumn,
    req: types.RelationalRowsJoinRequest,
    now_ns: u64,
) !bool {
    if (!joinHasOnExpressionPredicates(req)) return true;

    var parsed_right = std.json.parseFromSlice(std.json.Value, alloc, right_row_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed_right.deinit();
    if (parsed_right.value != .object) return error.InvalidQueryRequest;
    for (req.on_expression_predicates) |condition| {
        if (!(try expressionConditionMatchesWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, condition, left_columns, right_columns, now_ns))) return false;
    }
    if (!(try expressionOrPredicateGroupsPassWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, req.on_expression_or_predicates, left_columns, right_columns, now_ns))) return false;
    if (!(try expressionNotPredicateGroupsPassWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, req.on_expression_not_predicates, left_columns, right_columns, now_ns))) return false;
    for (req.on_expression_array_contains) |predicate| {
        if (!(try queryExpressionArrayContainsPredicatePassesWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, predicate, left_columns, right_columns, now_ns))) return false;
    }
    return true;
}

fn joinMatchPredicatesPass(
    alloc: Allocator,
    left_row: std.json.Value,
    left_columns: []const schema_mod.RelationalColumn,
    right_row_json: []const u8,
    right_columns: []const schema_mod.RelationalColumn,
    req: types.RelationalRowsJoinRequest,
    now_ns: u64,
) !bool {
    if (!joinHasMatchPredicates(req)) return true;

    var parsed_right = std.json.parseFromSlice(std.json.Value, alloc, right_row_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed_right.deinit();
    if (parsed_right.value != .object) return error.InvalidQueryRequest;
    for (req.match_expression_predicates) |condition| {
        if (!(try expressionConditionMatchesWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, condition, left_columns, right_columns, now_ns))) return false;
    }
    if (!(try expressionOrPredicateGroupsPassWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, req.match_expression_or_predicates, left_columns, right_columns, now_ns))) return false;
    if (!(try expressionNotPredicateGroupsPassWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, req.match_expression_not_predicates, left_columns, right_columns, now_ns))) return false;
    for (req.match_expression_array_contains) |predicate| {
        if (!(try queryExpressionArrayContainsPredicatePassesWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, predicate, left_columns, right_columns, now_ns))) return false;
    }
    return true;
}

const JoinRightList = struct {
    indexes: std.ArrayListUnmanaged(usize) = .empty,

    fn deinit(self: *@This(), alloc: Allocator) void {
        self.indexes.deinit(alloc);
        self.* = undefined;
    }
};

fn deinitJoinRightIndex(
    alloc: Allocator,
    index: *std.StringArrayHashMapUnmanaged(JoinRightList),
) void {
    for (index.keys()) |key| alloc.free(key);
    for (index.values()) |*list| list.deinit(alloc);
    index.deinit(alloc);
}

pub fn joinKeyJsonAlloc(
    alloc: Allocator,
    row: std.json.Value,
    predicates: []const types.RelationalRowsJoinOn,
    side: JoinSide,
) !?[]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('[');
    for (predicates, 0..) |predicate, i| {
        const field = switch (side) {
            .left => predicate.left_field,
            .right => predicate.right_field,
        };
        const value = jsonValueAtPath(row, field) orelse {
            out.deinit();
            return null;
        };
        if (value.* == .null) {
            out.deinit();
            return null;
        }
        if (i != 0) try writer.writeByte(',');
        try std.json.Stringify.value(value.*, .{}, writer);
    }
    try writer.writeByte(']');
    return try out.toOwnedSlice();
}

pub fn joinedRowJsonAlloc(
    alloc: Allocator,
    left_row_json: ?[]const u8,
    right_row_json: ?[]const u8,
    select: []const types.RelationalRowsJoinProjection,
) ![]u8 {
    var parsed_left = if (left_row_json) |json|
        std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidQueryRequest
    else
        null;
    defer if (parsed_left) |*parsed| parsed.deinit();
    if (parsed_left != null and parsed_left.?.value != .object) return error.InvalidQueryRequest;
    var parsed_right = if (right_row_json) |json|
        std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidQueryRequest
    else
        null;
    defer if (parsed_right) |*parsed| parsed.deinit();
    if (parsed_right != null and parsed_right.?.value != .object) return error.InvalidQueryRequest;

    if (select.len == 0) {
        var out: std.Io.Writer.Allocating = .init(alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeAll("{\"left\":");
        if (parsed_left) |parsed| {
            try std.json.Stringify.value(parsed.value, .{}, writer);
        } else {
            try writer.writeAll("null");
        }
        try writer.writeAll(",\"right\":");
        if (parsed_right) |parsed| {
            try std.json.Stringify.value(parsed.value, .{}, writer);
        } else {
            try writer.writeAll("null");
        }
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    for (select, 0..) |projection, i| {
        if (projection.output.len == 0 or projection.field.len == 0) return error.InvalidQueryRequest;
        if (i != 0) try writer.writeByte(',');
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        const value = switch (projection.side) {
            .left => if (parsed_left) |parsed| jsonValueAtPath(parsed.value, projection.field) else null,
            .right => if (parsed_right) |parsed| jsonValueAtPath(parsed.value, projection.field) else null,
        };
        if (value) |selected| {
            try std.json.Stringify.value(selected.*, .{}, writer);
        } else {
            try writer.writeAll("null");
        }
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

pub fn lateralHasMatchPredicates(req: types.RelationalRowsLateralRequest) bool {
    return req.match_expression_predicates.len != 0 or
        req.match_expression_or_predicates.len != 0 or
        req.match_expression_not_predicates.len != 0 or
        req.match_expression_array_contains.len != 0;
}

pub const LateralRightQueryFn = *const fn (
    ctx: ?*anyopaque,
    alloc: Allocator,
    right_source: types.RelationalRowsQueryRequest,
) anyerror!types.RelationalRowsQueryResult;

pub fn lateralFromLeftRowsAlloc(
    alloc: Allocator,
    req: types.RelationalRowsLateralRequest,
    left_rows: []const []const u8,
    right_query_ctx: ?*anyopaque,
    right_query_fn: LateralRightQueryFn,
    now_ns: u64,
) !types.RelationalRowsJoinResult {
    return try lateralFromLeftRowsWithColumnsAlloc(alloc, req, left_rows, &.{}, &.{}, right_query_ctx, right_query_fn, now_ns);
}

pub fn lateralFromLeftRowsWithColumnsAlloc(
    alloc: Allocator,
    req: types.RelationalRowsLateralRequest,
    left_rows: []const []const u8,
    left_columns: []const schema_mod.RelationalColumn,
    right_columns: []const schema_mod.RelationalColumn,
    right_query_ctx: ?*anyopaque,
    right_query_fn: LateralRightQueryFn,
    now_ns: u64,
) !types.RelationalRowsJoinResult {
    var joined = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (joined.items) |row| alloc.free(@constCast(row));
        joined.deinit(alloc);
    }

    for (left_rows) |left_row| {
        var parsed_left = std.json.parseFromSlice(std.json.Value, alloc, left_row, .{}) catch return error.InvalidQueryRequest;
        defer parsed_left.deinit();
        if (parsed_left.value != .object) return error.InvalidQueryRequest;

        const correlated_predicates = try lateralCorrelationPredicatesAlloc(alloc, parsed_left.value, req.correlations);
        defer {
            freeRelationalChecks(alloc, correlated_predicates);
            if (correlated_predicates.len > 0) alloc.free(correlated_predicates);
        }

        var right_rows: ?types.RelationalRowsQueryResult = null;
        if (correlated_predicates.len == req.correlations.len) {
            var right_source = fullRowSourceQuery(req.right);
            right_source.predicates = try concatRelationalChecksAlloc(alloc, req.right.predicates, correlated_predicates);
            defer {
                freeRelationalChecks(alloc, right_source.predicates);
                if (right_source.predicates.len > 0) alloc.free(right_source.predicates);
            }
            right_rows = try right_query_fn(right_query_ctx, alloc, right_source);
        }
        defer if (right_rows) |*rows| rows.deinit(alloc);

        var matched = false;
        if (right_rows) |rows| {
            for (rows.rows) |right_row| {
                if (!(try lateralMatchPredicatesPassWithColumns(alloc, parsed_left.value, left_columns, right_row, right_columns, req, now_ns))) continue;
                const row_json = try joinedRowJsonAlloc(alloc, left_row, right_row, req.select);
                var row_transferred = false;
                errdefer if (!row_transferred) alloc.free(row_json);
                try joined.append(alloc, row_json);
                row_transferred = true;
                matched = true;
            }
        }
        if (!matched and !lateralHasMatchPredicates(req)) {
            const row_json = try joinedRowJsonAlloc(alloc, left_row, null, req.select);
            var row_transferred = false;
            errdefer if (!row_transferred) alloc.free(row_json);
            try joined.append(alloc, row_json);
            row_transferred = true;
        }
    }

    try sortOutputRowsAlloc(alloc, joined.items, req.order_by, now_ns);

    const total_rows: u32 = @intCast(joined.items.len);
    const start = @min(@as(usize, req.offset), joined.items.len);
    const limited_len: usize = if (req.limit) |limit|
        @min(@as(usize, limit), joined.items.len - start)
    else
        joined.items.len - start;
    if (start > 0 or limited_len < joined.items.len) {
        for (joined.items[0..start]) |row| alloc.free(@constCast(row));
        for (joined.items[start + limited_len ..]) |row| alloc.free(@constCast(row));
        const kept = try alloc.dupe([]const u8, joined.items[start .. start + limited_len]);
        joined.deinit(alloc);
        return .{ .rows = kept, .total_rows = total_rows };
    }

    return .{
        .rows = try joined.toOwnedSlice(alloc),
        .total_rows = total_rows,
    };
}

fn lateralMatchPredicatesPass(
    alloc: Allocator,
    left_row: std.json.Value,
    right_row_json: []const u8,
    req: types.RelationalRowsLateralRequest,
    now_ns: u64,
) !bool {
    return try lateralMatchPredicatesPassWithColumns(alloc, left_row, &.{}, right_row_json, &.{}, req, now_ns);
}

fn lateralMatchPredicatesPassWithColumns(
    alloc: Allocator,
    left_row: std.json.Value,
    left_columns: []const schema_mod.RelationalColumn,
    right_row_json: []const u8,
    right_columns: []const schema_mod.RelationalColumn,
    req: types.RelationalRowsLateralRequest,
    now_ns: u64,
) !bool {
    if (!lateralHasMatchPredicates(req)) return true;

    var parsed_right = std.json.parseFromSlice(std.json.Value, alloc, right_row_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed_right.deinit();
    if (parsed_right.value != .object) return error.InvalidQueryRequest;
    for (req.match_expression_predicates) |condition| {
        if (!(try expressionConditionMatchesWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, condition, left_columns, right_columns, now_ns))) return false;
    }
    if (!(try expressionOrPredicateGroupsPassWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, req.match_expression_or_predicates, left_columns, right_columns, now_ns))) return false;
    if (!(try expressionNotPredicateGroupsPassWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, req.match_expression_not_predicates, left_columns, right_columns, now_ns))) return false;
    for (req.match_expression_array_contains) |predicate| {
        if (!(try queryExpressionArrayContainsPredicatePassesWithSourcesAndColumnSets(alloc, left_row, null, parsed_right.value, predicate, left_columns, right_columns, now_ns))) return false;
    }
    return true;
}

fn lateralCorrelationPredicatesAlloc(
    alloc: Allocator,
    left_row: std.json.Value,
    correlations: []const types.RelationalRowsLateralCorrelation,
) ![]schema_mod.RelationalCheck {
    const predicates = try alloc.alloc(schema_mod.RelationalCheck, correlations.len);
    var initialized: usize = 0;
    errdefer {
        freeRelationalChecks(alloc, predicates[0..initialized]);
        alloc.free(predicates);
    }
    for (correlations) |correlation| {
        const selected = jsonValueAtPath(left_row, correlation.left_field) orelse break;
        if (selected.* == .null) break;
        const value_json = switch (selected.*) {
            .bool, .integer, .float, .string => try std.json.Stringify.valueAlloc(alloc, selected.*, .{}),
            else => return error.InvalidQueryRequest,
        };
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        const name = try alloc.dupe(u8, "");
        var name_transferred = false;
        errdefer if (!name_transferred) alloc.free(name);
        predicates[initialized] = .{
            .name = name,
            .field = try alloc.dupe(u8, correlation.right_field),
            .op = .eq,
            .value_json = value_json,
        };
        initialized += 1;
        name_transferred = true;
        value_transferred = true;
    }
    if (initialized != correlations.len) {
        freeRelationalChecks(alloc, predicates[0..initialized]);
        alloc.free(predicates);
        return &.{};
    }
    return predicates;
}

fn concatRelationalChecksAlloc(
    alloc: Allocator,
    base: []const schema_mod.RelationalCheck,
    extra: []const schema_mod.RelationalCheck,
) ![]schema_mod.RelationalCheck {
    const out = try alloc.alloc(schema_mod.RelationalCheck, base.len + extra.len);
    var initialized: usize = 0;
    errdefer {
        freeRelationalChecks(alloc, out[0..initialized]);
        alloc.free(out);
    }
    for (base) |predicate| {
        out[initialized] = try schema_mod.cloneRelationalCheckAlloc(alloc, predicate);
        initialized += 1;
    }
    for (extra) |predicate| {
        out[initialized] = try schema_mod.cloneRelationalCheckAlloc(alloc, predicate);
        initialized += 1;
    }
    return out;
}

fn freeRelationalChecks(alloc: Allocator, predicates: []const schema_mod.RelationalCheck) void {
    for (predicates) |predicate| {
        schema_mod.freeRelationalCheck(alloc, predicate);
    }
}

pub fn validateJoinedMutationCteReferences(req: types.RelationalRowsJoinedMutationSourceRequest) !void {
    const target = joinedMutationTargetQuery(req);
    const source = joinedMutationSourceQuery(req);
    if (target.source_cte.len != 0) return error.UnsupportedQueryRequest;
    if (req.ctes.len == 0) {
        if (source.source_cte.len != 0) return error.InvalidQueryRequest;
        return;
    }
    if (source.source_cte.len == 0) return error.InvalidQueryRequest;
    try validateMaterializedCtes(req.ctes, &.{});
    try validateFinalCteReference(req.ctes, source.source_cte);
}

pub fn validateJoinedMutationJoinFieldsForSide(
    runtime_schema: schema_mod.TableSchema,
    req: types.RelationalRowsJoinedMutationSourceRequest,
    side: JoinSide,
) !void {
    for (req.join.on) |predicate| {
        const field = switch (side) {
            .left => predicate.left_field,
            .right => predicate.right_field,
        };
        _ = findColumn(runtime_schema.relational_columns, field) orelse return error.InvalidQueryRequest;
    }
}

pub fn validateJoinedMutationJoinFieldsForOutputFields(
    output_fields: []const []const u8,
    req: types.RelationalRowsJoinedMutationSourceRequest,
    side: JoinSide,
) !void {
    for (req.join.on) |predicate| {
        const field = switch (side) {
            .left => predicate.left_field,
            .right => predicate.right_field,
        };
        try validateOutputField(output_fields, field);
    }
}

pub fn validateJoinedMutationMatchExpressions(
    target_schema: schema_mod.TableSchema,
    source_schema: schema_mod.TableSchema,
    req: types.RelationalRowsJoinedMutationSourceRequest,
) !void {
    for (req.match_expression_predicates) |condition| {
        try validateJoinedMutationMatchExpressionCondition(target_schema, source_schema, condition);
    }
    for (req.match_expression_or_predicates) |group| {
        for (group.conditions) |condition| {
            try validateJoinedMutationMatchExpressionCondition(target_schema, source_schema, condition);
        }
    }
    for (req.match_expression_not_predicates) |group| {
        for (group.conditions) |condition| {
            try validateJoinedMutationMatchExpressionCondition(target_schema, source_schema, condition);
        }
    }
    for (req.match_expression_array_contains) |predicate| {
        try validateJoinedMutationMatchExpression(target_schema, source_schema, predicate.expression);
    }
}

fn validateJoinedMutationMatchExpressionCondition(
    target_schema: schema_mod.TableSchema,
    source_schema: schema_mod.TableSchema,
    condition: types.RelationalRowsExpressionCondition,
) anyerror!void {
    try validateJoinedMutationMatchExpression(target_schema, source_schema, condition.lhs);
    for (condition.rhs) |rhs| try validateJoinedMutationMatchExpression(target_schema, source_schema, rhs);
}

fn validateJoinedMutationMatchExpression(
    target_schema: schema_mod.TableSchema,
    source_schema: schema_mod.TableSchema,
    expression: types.RelationalRowsExpression,
) anyerror!void {
    if (expression.kind == .field) {
        if (expression.field_source == .existing or expression.field_source == .proposed) return error.InvalidQueryRequest;
        const schema = if (expression.field_source == .source) source_schema else target_schema;
        _ = findColumn(schema.relational_columns, expression.field) orelse return error.InvalidQueryRequest;
    }
    for (expression.operands) |operand| try validateJoinedMutationMatchExpression(target_schema, source_schema, operand);
    for (expression.case_branches) |branch| {
        try validateJoinedMutationMatchExpressionCondition(target_schema, source_schema, branch.when);
        try validateJoinedMutationMatchExpression(target_schema, source_schema, branch.then);
    }
    for (expression.case_else) |case_else| try validateJoinedMutationMatchExpression(target_schema, source_schema, case_else);
}

pub fn validateMutationReturningRequestOutputs(
    runtime_schema: schema_mod.TableSchema,
    fields: []const []const u8,
    returning_all: bool,
    expressions: []const types.RelationalRowsExpressionProjection,
) !void {
    if (returning_all and fields.len != 0) return error.InvalidQueryRequest;
    for (fields) |field| {
        if (field.len == 0) return error.InvalidQueryRequest;
        if (findColumn(runtime_schema.relational_columns, field) == null and
            !jsonColumnSubpathIsValid(runtime_schema.relational_columns, field))
        {
            return error.InvalidQueryRequest;
        }
        if (mutationReturningOutputCount(fields, expressions, field) > 1) return error.InvalidQueryRequest;
    }
    for (expressions) |projection| {
        if (projection.output.len == 0) return error.InvalidQueryRequest;
        if (returning_all and findColumn(runtime_schema.relational_columns, projection.output) != null) return error.InvalidQueryRequest;
        if (mutationReturningOutputCount(fields, expressions, projection.output) > 1) return error.InvalidQueryRequest;
    }
}

pub fn validateMutationReturningTargetExpressions(
    runtime_schema: schema_mod.TableSchema,
    expressions: []const types.RelationalRowsExpressionProjection,
) !void {
    for (expressions) |projection| try validateMutationReturningTargetExpression(runtime_schema, projection.expression);
}

fn validateMutationReturningTargetExpressionCondition(
    runtime_schema: schema_mod.TableSchema,
    condition: types.RelationalRowsExpressionCondition,
) anyerror!void {
    try validateMutationReturningTargetExpression(runtime_schema, condition.lhs);
