fn appendJoinedJsonSetExpressionOpsAlloc(
    alloc: Allocator,
    target_schema: schema_mod.TableSchema,
    target_row: std.json.Value,
    source_row: std.json.Value,
    operations: *std.ArrayListUnmanaged(types.TransformOp),
