    var parsed = std.json.parseFromSlice(std.json.Value, alloc, source_rows[target], .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidQueryRequest;
    const expression = window.value_expression orelse return error.InvalidQueryRequest;
    const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression, now_ns);
    defer alloc.free(value_json);
    try writer.writeAll(value_json);
}

fn writeRelationalRowsWindowNthValue(
    alloc: Allocator,
    writer: *std.Io.Writer,
    source_rows: []const []const u8,
    partition_keys: []const []const u8,
    order_keys: []const []QueryOrderKey,
    row_index: usize,
    window: types.RelationalRowsWindowSpec,
    now_ns: u64,
) !void {
    if (window.offset == 0) return error.InvalidQueryRequest;
    const frame = relationalRowsWindowFrame(window);
    const range = (try relationalRowsWindowFrameRange(source_rows, partition_keys, order_keys, window.order_by, row_index, frame)) orelse {
        try writer.writeAll("null");
        return;
    };
    const offset: usize = @intCast(window.offset - 1);
    if (offset > range.end - range.start) {
        try writer.writeAll("null");
        return;
    }
    const target = range.start + offset;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, source_rows[target], .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidQueryRequest;
    const expression = window.value_expression orelse return error.InvalidQueryRequest;
    const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression, now_ns);
    defer alloc.free(value_json);
    try writer.writeAll(value_json);
}

fn writeRelationalRowsWindowCount(
    alloc: Allocator,
    writer: *std.Io.Writer,
    source_rows: []const []const u8,
    source_columns: []const schema_mod.RelationalColumn,
    partition_keys: []const []const u8,
    order_keys: []const []QueryOrderKey,
    row_index: usize,
    window: types.RelationalRowsWindowSpec,
    now_ns: u64,
) !void {
    const frame = relationalRowsWindowFrame(window);
    const range = (try relationalRowsWindowFrameRange(source_rows, partition_keys, order_keys, window.order_by, row_index, frame)) orelse {
        try writer.writeAll("0");
        return;
    };
    var count: u64 = 0;
    if (window.value_expression) |expression| {
        for (source_rows[range.start .. range.end + 1]) |row_json| {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
            defer parsed.deinit();
            if (parsed.value != .object) return error.InvalidQueryRequest;
            if (!(try relationalRowsWindowFilterPasses(alloc, parsed.value, window, source_columns, now_ns))) continue;
            const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression, now_ns);
            defer alloc.free(value_json);
            var value = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidQueryRequest;
            defer value.deinit();
            if (value.value != .null) count += 1;
        }
    } else if (!windowHasFilters(window)) {
        count = @intCast(range.end - range.start + 1);
    } else {
        for (source_rows[range.start .. range.end + 1]) |row_json| {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
            defer parsed.deinit();
            if (parsed.value != .object) return error.InvalidQueryRequest;
            if (try relationalRowsWindowFilterPasses(alloc, parsed.value, window, source_columns, now_ns)) count += 1;
        }
    }
    try writer.print("{d}", .{count});
}

fn relationalRowsWindowFilterPasses(
    alloc: Allocator,
    row: std.json.Value,
    window: types.RelationalRowsWindowSpec,
    source_columns: []const schema_mod.RelationalColumn,
    now_ns: u64,
) !bool {
    return try aggregateFilterPassesWithColumns(
        alloc,
        row,
        window.filter_predicates,
        window.filter_array_any,
        window.filter_array_contains,
        window.filter_array_eq,
        window.filter_in_predicates,
        window.filter_json_contains,
        window.filter_json_path_eq,
        window.filter_json_path_exists,
        window.filter_text_patterns,
        window.filter_expressions,
        window.filter_expression_array_contains,
        window.filter_any,
        window.filter_not,
        source_columns,
        now_ns,
    );
}

fn writeRelationalRowsWindowNumericAggregate(
    alloc: Allocator,
    writer: *std.Io.Writer,
    source_rows: []const []const u8,
    source_columns: []const schema_mod.RelationalColumn,
    partition_keys: []const []const u8,
    order_keys: []const []QueryOrderKey,
    row_index: usize,
    window: types.RelationalRowsWindowSpec,
    now_ns: u64,
) !void {
    const frame = relationalRowsWindowFrame(window);
    const range = (try relationalRowsWindowFrameRange(source_rows, partition_keys, order_keys, window.order_by, row_index, frame)) orelse {
        try writer.writeAll("null");
        return;
    };
    const expression = window.value_expression orelse return error.InvalidQueryRequest;
    var count: u64 = 0;
    var sum: f64 = 0;
    for (source_rows[range.start .. range.end + 1]) |row_json| {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidQueryRequest;
        if (!(try relationalRowsWindowFilterPasses(alloc, parsed.value, window, source_columns, now_ns))) continue;
        const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression, now_ns);
        defer alloc.free(value_json);
        var value = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidQueryRequest;
        defer value.deinit();
        if (value.value == .null) continue;
        const number = jsonNumberAsF64(value.value) orelse return error.InvalidQueryRequest;
        switch (window.function) {
            .sum, .avg => sum += number,
            else => return error.InvalidQueryRequest,
        }
        count += 1;
    }
    if (count == 0) {
        try writer.writeAll("null");
        return;
    }
    const result = switch (window.function) {
        .sum => sum,
        .avg => sum / @as(f64, @floatFromInt(count)),
        else => return error.InvalidQueryRequest,
    };
    try writer.print("{d}", .{result});
}

fn writeRelationalRowsWindowScalarExtrema(
    alloc: Allocator,
    writer: *std.Io.Writer,
    source_rows: []const []const u8,
    source_columns: []const schema_mod.RelationalColumn,
    partition_keys: []const []const u8,
    order_keys: []const []QueryOrderKey,
    row_index: usize,
    window: types.RelationalRowsWindowSpec,
    now_ns: u64,
) !void {
    const frame = relationalRowsWindowFrame(window);
    const range = (try relationalRowsWindowFrameRange(source_rows, partition_keys, order_keys, window.order_by, row_index, frame)) orelse {
        try writer.writeAll("null");
        return;
    };
    const expression = window.value_expression orelse return error.InvalidQueryRequest;
    var best_json: ?[]u8 = null;
    defer if (best_json) |json| alloc.free(json);

    for (source_rows[range.start .. range.end + 1]) |row_json| {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidQueryRequest;
        if (!(try relationalRowsWindowFilterPasses(alloc, parsed.value, window, source_columns, now_ns))) continue;
        const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression, now_ns);
        defer alloc.free(value_json);
        var value = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidQueryRequest;
        defer value.deinit();
        if (value.value == .null) continue;
        if (best_json == null) {
            best_json = try alloc.dupe(u8, value_json);
            continue;
        }

        var parsed_best = std.json.parseFromSlice(std.json.Value, alloc, best_json.?, .{}) catch return error.InvalidQueryRequest;
        defer parsed_best.deinit();
        const comparison = compareJsonScalars(value.value, parsed_best.value) orelse return error.InvalidQueryRequest;
        const replace = switch (window.function) {
            .min => comparison == .lt,
            .max => comparison == .gt,
            else => return error.InvalidQueryRequest,
        };
        if (!replace) continue;
        const next = try alloc.dupe(u8, value_json);
        alloc.free(best_json.?);
        best_json = next;
    }
    if (best_json) |json| {
        try writer.writeAll(json);
    } else {
        try writer.writeAll("null");
    }
}

fn writeRelationalRowsWindowBooleanAggregate(
    alloc: Allocator,
    writer: *std.Io.Writer,
    source_rows: []const []const u8,
    source_columns: []const schema_mod.RelationalColumn,
    partition_keys: []const []const u8,
    order_keys: []const []QueryOrderKey,
    row_index: usize,
    window: types.RelationalRowsWindowSpec,
    now_ns: u64,
) !void {
    const frame = relationalRowsWindowFrame(window);
    const range = (try relationalRowsWindowFrameRange(source_rows, partition_keys, order_keys, window.order_by, row_index, frame)) orelse {
        try writer.writeAll("null");
        return;
    };
    const expression = window.value_expression orelse return error.InvalidQueryRequest;
    var count: u64 = 0;
    var bool_or = false;
    var bool_and = true;
    for (source_rows[range.start .. range.end + 1]) |row_json| {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidQueryRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidQueryRequest;
        if (!(try relationalRowsWindowFilterPasses(alloc, parsed.value, window, source_columns, now_ns))) continue;
        const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression, now_ns);
        defer alloc.free(value_json);
        var value = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidQueryRequest;
        defer value.deinit();
        if (value.value == .null) continue;
        if (value.value != .bool) return error.InvalidQueryRequest;
        count += 1;
        bool_or = bool_or or value.value.bool;
        bool_and = bool_and and value.value.bool;
    }
    if (count == 0) {
        try writer.writeAll("null");
        return;
    }
    const result = switch (window.function) {
        .bool_or => bool_or,
        .bool_and => bool_and,
        else => return error.InvalidQueryRequest,
    };
    try writer.writeAll(if (result) "true" else "false");
}

fn writeRelationalRowsWindowOffsetValue(
    alloc: Allocator,
    writer: *std.Io.Writer,
    source_rows: []const []const u8,
    partition_keys: []const []const u8,
    row_index: usize,
    window: types.RelationalRowsWindowSpec,
    now_ns: u64,
) !void {
    const target_index: ?usize = switch (window.function) {
        .lag => if (row_index >= window.offset) row_index - window.offset else null,
        .lead => blk: {
            const remaining = source_rows.len - row_index - 1;
            if (window.offset > remaining) break :blk null;
            const target = row_index + window.offset;
            break :blk if (target < source_rows.len) target else null;
        },
        else => return error.InvalidQueryRequest,
    };
    const target = target_index orelse {
        try writeRelationalRowsWindowDefaultValue(alloc, writer, window.default_json);
        return;
    };
    if (!std.mem.eql(u8, partition_keys[row_index], partition_keys[target])) {
        try writeRelationalRowsWindowDefaultValue(alloc, writer, window.default_json);
        return;
    }
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, source_rows[target], .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidQueryRequest;
    const expression = window.value_expression orelse return error.InvalidQueryRequest;
    const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression, now_ns);
    defer alloc.free(value_json);
    try writer.writeAll(value_json);
}

fn writeRelationalRowsWindowDefaultValue(
    alloc: Allocator,
    writer: *std.Io.Writer,
    default_json: []const u8,
) !void {
    if (default_json.len == 0) {
        try writer.writeAll("null");
        return;
    }
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, default_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    try std.json.Stringify.value(parsed.value, .{}, writer);
}

pub fn validateWindowRequestAlloc(
    alloc: Allocator,
    req: types.RelationalRowsWindowRequest,
) !void {
    const source_order = try validateWindowRequestAndSourceOrderAlloc(alloc, req);
    alloc.free(source_order);
}

pub fn validateWindowRequestAndSourceOrderAlloc(
    alloc: Allocator,
    req: types.RelationalRowsWindowRequest,
) ![]types.RelationalRowsQueryOrder {
    if (req.windows.len == 0) return error.InvalidQueryRequest;
    if (req.source.row_claim != null) return error.UnsupportedQueryRequest;
    if (req.source.doc_key_range != null and req.source.source_cte.len != 0) return error.InvalidQueryRequest;
    try validateWindowOutputNames(req);
    const first_window = req.windows[0];
    for (req.windows) |window| {
        if (window.output.len == 0) return error.InvalidQueryRequest;
        try validateWindowFrameSpec(window);
        switch (window.function) {
            .row_number, .rank, .dense_rank, .percent_rank, .cume_dist => {
                if (window.value_expression != null or window.offset != 1 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
            .ntile => {
                if (window.value_expression != null or window.offset == 0 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
            .lag, .lead => {
                if (window.value_expression == null or window.offset == 0) return error.InvalidQueryRequest;
            },
            .first_value => {
                if (window.value_expression == null or window.offset != 1 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
            .last_value => {
                if (window.value_expression == null or window.offset != 1 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
            .nth_value => {
                if (window.value_expression == null or window.offset == 0 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
            .count => {
                if (window.offset != 1 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
            .sum, .avg, .min, .max => {
                if (window.value_expression == null or window.offset != 1 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
            .bool_or, .bool_and => {
                if (window.value_expression == null or window.offset != 1 or window.default_json.len > 0) return error.InvalidQueryRequest;
            },
        }
        if (window.order_by.len == 0 and windowFunctionRequiresOrder(window.function)) return error.InvalidQueryRequest;
        if (!windowFunctionSupportsFilter(window.function) and windowHasFilters(window)) return error.InvalidQueryRequest;
    }

    return try windowSourceOrderAlloc(alloc, first_window);
}

fn validateWindowFrameSpec(window: types.RelationalRowsWindowSpec) !void {
    const frame = window.frame orelse return;
    if (window.order_by.len == 0) return error.InvalidQueryRequest;
    if (frame.start == .unbounded_following or frame.end == .unbounded_preceding) return error.InvalidQueryRequest;
    try validateWindowFrameBoundOffset(frame.start, frame.start_offset);
    try validateWindowFrameBoundOffset(frame.end, frame.end_offset);
    if (windowFrameBoundOrdinal(frame.start, frame.start_offset) > windowFrameBoundOrdinal(frame.end, frame.end_offset)) return error.InvalidQueryRequest;
    if (frame.unit != .range or !windowFrameHasOffset(frame)) return;
    const order = window.order_by[0];
    if (order.null_test != null) return error.InvalidQueryRequest;
    if (order.field.len == 0 and order.expression == null) return error.InvalidQueryRequest;
}

fn validateWindowFrameBoundOffset(
    bound: types.RelationalRowsWindowFrameBound,
    offset: u32,
) !void {
    switch (bound) {
        .offset_preceding, .offset_following => {
            if (offset == 0) return error.InvalidQueryRequest;
        },
        else => if (offset != 0) return error.InvalidQueryRequest,
    }
}

fn windowFrameHasOffset(frame: types.RelationalRowsWindowFrame) bool {
    return frame.start == .offset_preceding or
        frame.start == .offset_following or
        frame.end == .offset_preceding or
        frame.end == .offset_following;
}

fn windowFrameBoundOrdinal(bound: types.RelationalRowsWindowFrameBound, offset: u32) i64 {
    return switch (bound) {
        .unbounded_preceding => std.math.minInt(i64),
        .offset_preceding => -@as(i64, @intCast(offset)),
        .current_row => 0,
        .offset_following => @as(i64, @intCast(offset)),
        .unbounded_following => std.math.maxInt(i64),
    };
}

fn windowFunctionSupportsFilter(function: types.RelationalRowsWindowFunction) bool {
    return switch (function) {
        .count, .sum, .avg, .min, .max, .bool_or, .bool_and => true,
        else => false,
    };
}

fn windowFunctionRequiresOrder(function: types.RelationalRowsWindowFunction) bool {
    return switch (function) {
        .count, .sum, .avg, .min, .max, .bool_or, .bool_and => false,
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile, .lag, .lead, .first_value, .last_value, .nth_value => true,
    };
}

pub fn windowHasFilters(window: types.RelationalRowsWindowSpec) bool {
    return window.filter_predicates.len > 0 or
        window.filter_array_any.len > 0 or
        window.filter_array_contains.len > 0 or
        window.filter_array_eq.len > 0 or
        window.filter_in_predicates.len > 0 or
        window.filter_json_contains.len > 0 or
        window.filter_json_path_eq.len > 0 or
        window.filter_json_path_exists.len > 0 or
        window.filter_text_patterns.len > 0 or
        window.filter_expressions.len > 0 or
        window.filter_expression_array_contains.len > 0 or
        window.filter_any.len > 0 or
        window.filter_not.len > 0;
}

fn validateWindowOutputNames(req: types.RelationalRowsWindowRequest) !void {
    if (!req.select_all) {
        for (req.select) |field| {
            if (field.len == 0) return error.InvalidQueryRequest;
            if (windowExplicitOutputNameCount(req, field) > 1) return error.InvalidQueryRequest;
        }
    }
    for (req.windows) |window| {
        if (window.output.len == 0) return error.InvalidQueryRequest;
        if (windowExplicitOutputNameCount(req, window.output) > 1) return error.InvalidQueryRequest;
    }
}

fn windowExplicitOutputNameCount(
    req: types.RelationalRowsWindowRequest,
    name: []const u8,
) usize {
    var count: usize = 0;
    if (!req.select_all) {
        for (req.select) |field| {
            if (std.mem.eql(u8, field, name)) count += 1;
        }
    }
    for (req.windows) |window| {
        if (std.mem.eql(u8, window.output, name)) count += 1;
    }
    return count;
}

fn windowSourceOrderAlloc(
    alloc: Allocator,
    window: types.RelationalRowsWindowSpec,
) ![]types.RelationalRowsQueryOrder {
    const out = try alloc.alloc(types.RelationalRowsQueryOrder, window.partition_by.len + window.order_by.len);
    for (window.partition_by, 0..) |field, i| out[i] = .{ .field = field, .direction = .asc };
    for (window.order_by, 0..) |order, i| out[window.partition_by.len + i] = order;
    return out;
}

fn applyWindowSourceOrderCollations(
    order_by: []types.RelationalRowsQueryOrder,
    source_columns: []const schema_mod.RelationalColumn,
) void {
    for (order_by) |*order| {
        if (order.collation != null) continue;
        if (order.expression) |expression| {
            order.collation = expressionDirectFieldCollationForColumnSets(source_columns, source_columns, expression);
        } else if (order.field.len != 0) {
            order.collation = distinctFieldCollation(source_columns, order.field);
        }
    }
}

fn resolvedQueryOrdersWithSourceCollationsAlloc(
    alloc: Allocator,
    order_by: []const types.RelationalRowsQueryOrder,
    source_columns: []const schema_mod.RelationalColumn,
) ![]types.RelationalRowsQueryOrder {
    if (order_by.len == 0) return &.{};
    const resolved = try alloc.dupe(types.RelationalRowsQueryOrder, order_by);
    applyWindowSourceOrderCollations(resolved, source_columns);
    return resolved;
}

fn freeResolvedQueryOrdersWithSourceCollations(
    alloc: Allocator,
    order_by: []types.RelationalRowsQueryOrder,
) void {
    if (order_by.len > 0) alloc.free(order_by);
}

fn resolvedAggregateSpecsWithSourceCollationsAlloc(
    alloc: Allocator,
    specs: []const types.RelationalRowsAggregateSpec,
    source_columns: []const schema_mod.RelationalColumn,
) ![]types.RelationalRowsAggregateSpec {
    if (specs.len == 0) return &.{};
    const resolved = try alloc.dupe(types.RelationalRowsAggregateSpec, specs);
    var initialized: usize = 0;
    errdefer {
        for (resolved[0..initialized]) |spec| freeResolvedQueryOrdersWithSourceCollations(alloc, @constCast(spec.array_order_by));
        alloc.free(resolved);
    }
    for (resolved) |*spec| {
        spec.array_order_by = try resolvedQueryOrdersWithSourceCollationsAlloc(alloc, spec.array_order_by, source_columns);
        initialized += 1;
    }
    return resolved;
}

fn freeResolvedAggregateSpecsWithSourceCollations(
    alloc: Allocator,
    specs: []types.RelationalRowsAggregateSpec,
) void {
    for (specs) |spec| freeResolvedQueryOrdersWithSourceCollations(alloc, @constCast(spec.array_order_by));
    if (specs.len > 0) alloc.free(specs);
}

pub fn validateFinalCteReference(
    ctes: []const types.RelationalRowsCte,
    name: []const u8,
) !void {
    if (name.len != 0 and !cteNameExists(ctes, name)) return error.InvalidQueryRequest;
}

fn cteNameExists(
    ctes: []const types.RelationalRowsCte,
    name: []const u8,
) bool {
    for (ctes) |cte| {
        if (std.mem.eql(u8, cte.name, name)) return true;
    }
    return false;
}

