        pub fn appendRelationalRowsQueryCandidateFromRawAlloc(
            self: *DB,
            alloc: Allocator,
            runtime_schema: schema_mod.TableSchema,
            req: types.RelationalRowsQueryRequest,
            rows: *std.ArrayListUnmanaged(QueryCandidate),
            doc_key: []const u8,
            raw_row: []const u8,
