        fn queryRelationalRowsTableFunctionCteAlloc(
            self: *DB,
            alloc: Allocator,
            cte_name: []const u8,
            table_function: types.RelationalRowsTableFunction,
            req: types.RelationalRowsQueryRequest,
        ) !types.RelationalRowsQueryResult {
            const rows = switch (table_function) {
                .graph_query => |graph_query| try @This().materializeGraphQueryTableFunctionRowsAlloc(self, alloc, graph_query),
                .graph_metric_query => |graph_metric_query| try @This().materializeGraphMetricTableFunctionRowsAlloc(self, alloc, graph_metric_query),
                .graph_metric_rerank_query => |graph_metric_rerank_query| try @This().materializeGraphMetricRerankTableFunctionRowsAlloc(self, alloc, graph_metric_rerank_query),
            };
            defer freeOwnedConstStringSlice(alloc, rows);
            var source_req = req;
            source_req.source_cte = "";
            return try @This().queryRelationalRowsFromSourceRowsAlloc(self, alloc, cte_name, rows, source_req);
        }

        fn materializeGraphQueryTableFunctionRowsAlloc(
            self: *DB,
            alloc: Allocator,
            graph_table_function: types.RelationalRowsGraphTableFunction,
        ) ![]const []const u8 {
            const graph_query = graph_table_function.query;
            var search_result = try self.search(alloc, .{
                .graph_queries = &.{graph_query},
                .include_stored = true,
            });
            defer search_result.deinit();

            var rows = std.ArrayListUnmanaged([]const u8).empty;
            errdefer freeOwnedConstStringArrayList(alloc, &rows);

            for (search_result.hits) |hit| {
                try rows.append(alloc, try graphTableFunctionHitRowJsonAlloc(alloc, graph_query.name, hit, null, null, graph_table_function.alias_projections));
            }
            for (search_result.graph_results) |graph_result| {
                for (graph_result.nodes) |node| {
                    try rows.append(alloc, try graphTableFunctionNodeRowJsonAlloc(alloc, graph_result.name, node, null, graph_table_function.alias_projections));
                }
                for (graph_result.matches) |match| {
                    const match_json = try graphPatternMatchJsonAlloc(alloc, match);
                    defer alloc.free(match_json);
                    if (graph_table_function.alias_projections.len > 0) {
                        try rows.append(alloc, try graphTableFunctionPatternMatchRowJsonAlloc(alloc, graph_result.name, match, match_json, graph_table_function.alias_projections));
                        continue;
                    }
                    if (match.bindings.len == 0) {
                        try rows.append(alloc, try graphTableFunctionSyntheticRowJsonAlloc(alloc, graph_result.name, match_json, graph_table_function.alias_projections));
                        continue;
                    }
                    for (match.bindings) |binding| {
                        try rows.append(alloc, try graphTableFunctionNodeRowJsonAlloc(alloc, graph_result.name, binding.node, match_json, graph_table_function.alias_projections));
                    }
                }
                for (graph_result.hits) |hit| {
                    try rows.append(alloc, try graphTableFunctionHitRowJsonAlloc(alloc, graph_result.name, hit, null, null, graph_table_function.alias_projections));
                }
            }
            return try rows.toOwnedSlice(alloc);
        }

        fn materializeGraphMetricTableFunctionRowsAlloc(
            self: *DB,
            alloc: Allocator,
            graph_metric_table_function: types.RelationalRowsGraphMetricTableFunction,
        ) ![]const []const u8 {
            const graph_metric_query = graph_metric_table_function.query;
            var search_result = try self.search(alloc, .{
                .graph_metric_queries = &.{graph_metric_query},
                .include_stored = false,
            });
            defer search_result.deinit();

            var rows = std.ArrayListUnmanaged([]const u8).empty;
            errdefer freeOwnedConstStringArrayList(alloc, &rows);

            for (search_result.graph_metric_results) |metric_result| {
                if (!std.mem.eql(u8, metric_result.name, graph_metric_query.name)) continue;
                for (metric_result.scores) |score| {
                    try rows.append(alloc, try graphMetricTableFunctionScoreRowJsonAlloc(alloc, metric_result.name, score));
                }
            }
            return try rows.toOwnedSlice(alloc);
        }

        fn materializeGraphMetricRerankTableFunctionRowsAlloc(
            self: *DB,
            alloc: Allocator,
            graph_metric_rerank_table_function: types.RelationalRowsGraphMetricRerankTableFunction,
        ) ![]const []const u8 {
            var search_result = try self.search(alloc, graph_metric_rerank_table_function.request);
            defer search_result.deinit();

            var rows = std.ArrayListUnmanaged([]const u8).empty;
            errdefer freeOwnedConstStringArrayList(alloc, &rows);

            for (search_result.hits) |hit| {
                try rows.append(alloc, try graphTableFunctionHitRowJsonAlloc(alloc, "graph_metric_rerank", hit, null, null, &.{}));
            }
            return try rows.toOwnedSlice(alloc);
        }

