            left_ranges: []const types.RelationalRowsDocKeyRange,
            right_ranges: []const types.RelationalRowsDocKeyRange,
        ) !types.RelationalRowsJoinResult {
            if (req.left.source_cte.len != 0 or req.right.source_cte.len != 0) return error.InvalidQueryRequest;
            if ((left_ranges.len == 0) != (right_ranges.len == 0)) return error.InvalidQueryRequest;
            try validateLateralRequest(req);
            try validateLateralOutputReferencesAlloc(alloc, req);
            try validateLateralAgainstSchema(runtime_schema, req);

            const left_source = lateralLeftSource(req.left);
            var left_rows = try self.queryRelationalRowsAcrossRanges(alloc, runtime_schema, left_source, left_ranges);
            defer left_rows.deinit(alloc);

            return try @This().lateralRelationalRowsFromLeftRowsAlloc(
                self,
                alloc,
                runtime_schema,
                .{ .ranges = right_ranges },
                req,
                left_rows.rows,
                runtime_schema.relational_columns,
                runtime_schema.relational_columns,
            );
        }

        pub fn lateralRelationalRowsFromSourceRowsAlloc(
            self: *DB,
            alloc: Allocator,
            runtime_schema: schema_mod.TableSchema,
            req: types.RelationalRowsLateralRequest,
            left_rows: []const []const u8,
            right_rows: []const []const u8,
        ) !types.RelationalRowsJoinResult {
            if (req.left.doc_key_range != null or req.right.doc_key_range != null) return error.InvalidQueryRequest;
            try validateLateralRequest(req);
            return try @This().lateralRelationalRowsFromLeftRowsAlloc(
                self,
                alloc,
                runtime_schema,
                .{ .source_rows = right_rows },
                req,
                left_rows,
                runtime_schema.relational_columns,
                runtime_schema.relational_columns,
            );
        }

        pub fn lateralRelationalRowsFromSourceRowsStaticAlloc(
            alloc: Allocator,
            req: types.RelationalRowsLateralRequest,
            left_rows: []const []const u8,
            right_rows: []const []const u8,
        ) !types.RelationalRowsJoinResult {
            if (req.left.doc_key_range != null or req.right.doc_key_range != null) return error.InvalidQueryRequest;
            try validateLateralRequest(req);
            var ctx = RelationalRowsStaticLateralRightQueryContext{ .source_right_rows = right_rows };
            return try lateralFromLeftRowsAlloc(alloc, req, left_rows, &ctx, queryRelationalRowsStaticLateralRightSourceCallback, currentTimeNs());
        }

        fn lateralRelationalRowsWithMaterializedCtesAlloc(
            self: *DB,
            alloc: Allocator,
            runtime_schema: schema_mod.TableSchema,
            materialized_ctes: []MaterializedCte,
            req: types.RelationalRowsLateralRequest,
        ) !types.RelationalRowsJoinResult {
            return try @This().lateralRelationalRowsWithMaterializedCtesAndRangesAlloc(self, alloc, runtime_schema, materialized_ctes, &.{}, &.{}, req);
        }

        fn lateralRelationalRowsWithMaterializedCtesAndRangesAlloc(
            self: *DB,
            alloc: Allocator,
            runtime_schema: schema_mod.TableSchema,
            materialized_ctes: []MaterializedCte,
            left_ranges: []const types.RelationalRowsDocKeyRange,
            right_ranges: []const types.RelationalRowsDocKeyRange,
            req: types.RelationalRowsLateralRequest,
        ) !types.RelationalRowsJoinResult {
            if ((left_ranges.len == 0) != (right_ranges.len == 0)) return error.InvalidQueryRequest;
            try validateLateralRequest(req);
            try validateLateralAgainstCteOutput(materialized_ctes, req);
            try validateLateralAgainstSchema(runtime_schema, req);
            try validateLateralOutputReferencesAlloc(alloc, req);

            const left_source = lateralLeftSource(req.left);
            var left_rows = try @This().queryRelationalRowsWithMaterializedCtesAndRangesAlloc(self, alloc, runtime_schema, materialized_ctes, left_ranges, left_source);
            defer left_rows.deinit(alloc);

            const left_columns = joinSideSourceColumns(runtime_schema, materialized_ctes, req.left);
            const right_columns = joinSideSourceColumns(runtime_schema, materialized_ctes, req.right);
            return try @This().lateralRelationalRowsFromLeftRowsAlloc(
                self,
                alloc,
                runtime_schema,
                .{ .materialized_ctes_and_ranges = .{ .ctes = materialized_ctes, .ranges = right_ranges } },
                req,
                left_rows.rows,
                left_columns,
                right_columns,
            );
        }

        const RelationalRowsLateralRightSource = union(enum) {
            materialized_ctes: []MaterializedCte,
            materialized_ctes_and_ranges: struct {
                ctes: []MaterializedCte,
                ranges: []const types.RelationalRowsDocKeyRange,
            },
            ranges: []const types.RelationalRowsDocKeyRange,
            source_rows: []const []const u8,
        };

        const RelationalRowsLateralRightQueryContext = struct {
            db: *DB,
            runtime_schema: schema_mod.TableSchema,
            right_source_kind: RelationalRowsLateralRightSource,
        };

        const RelationalRowsStaticLateralRightQueryContext = struct {
            source_right_rows: []const []const u8,
        };

        fn lateralRelationalRowsFromLeftRowsAlloc(
            self: *DB,
            alloc: Allocator,
            runtime_schema: schema_mod.TableSchema,
            right_source_kind: RelationalRowsLateralRightSource,
            req: types.RelationalRowsLateralRequest,
            left_rows: []const []const u8,
            left_columns: []const schema_mod.RelationalColumn,
            right_columns: []const schema_mod.RelationalColumn,
        ) !types.RelationalRowsJoinResult {
            var ctx = RelationalRowsLateralRightQueryContext{
                .db = self,
                .runtime_schema = runtime_schema,
                .right_source_kind = right_source_kind,
            };
            return try lateralFromLeftRowsWithColumnsAlloc(alloc, req, left_rows, left_columns, right_columns, &ctx, queryRelationalRowsLateralRightSourceCallback, currentTimeNs());
        }

        fn queryRelationalRowsForLateralRightSourceAlloc(
            self: *DB,
            alloc: Allocator,
            runtime_schema: schema_mod.TableSchema,
            right_source_kind: RelationalRowsLateralRightSource,
            right_source: types.RelationalRowsQueryRequest,
        ) !types.RelationalRowsQueryResult {
            return switch (right_source_kind) {
                .materialized_ctes => |materialized_ctes| try @This().queryRelationalRowsWithMaterializedCtesAlloc(self, alloc, runtime_schema, materialized_ctes, right_source),
                .materialized_ctes_and_ranges => |source| try @This().queryRelationalRowsWithMaterializedCtesAndRangesAlloc(self, alloc, runtime_schema, source.ctes, source.ranges, right_source),
                .ranges => |ranges| try self.queryRelationalRowsAcrossRanges(alloc, runtime_schema, right_source, ranges),
                .source_rows => |source_rows| try @This().queryRelationalRowsFromSourceRowsAlloc(self, alloc, "lateral_right", source_rows, right_source),
            };
        }

        fn queryRelationalRowsLateralRightSourceCallback(
            ctx: ?*anyopaque,
            alloc: Allocator,
            right_source: types.RelationalRowsQueryRequest,
        ) anyerror!types.RelationalRowsQueryResult {
            const state: *RelationalRowsLateralRightQueryContext = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            return try @This().queryRelationalRowsForLateralRightSourceAlloc(state.db, alloc, state.runtime_schema, state.right_source_kind, right_source);
        }

        fn queryRelationalRowsStaticLateralRightSourceCallback(
            ctx: ?*anyopaque,
            alloc: Allocator,
            right_source: types.RelationalRowsQueryRequest,
        ) anyerror!types.RelationalRowsQueryResult {
            const state: *RelationalRowsStaticLateralRightQueryContext = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            return try @This().queryRelationalRowsFromSourceRowsStaticAlloc(alloc, "lateral_right", state.source_right_rows, right_source);
        }
    };
}

pub fn admitRelationalRowsSetOperationRows(
    plan: types.RelationalRowsSetOperationPlan,
    rows: []const []const u8,
) !void {
    try admitRelationalRowsSetOperationRowsWithPolicy(plan, rows, .strict);
}

pub fn admitRelationalRowsSetOperationRowsAllowSpill(
    plan: types.RelationalRowsSetOperationPlan,
    rows: []const []const u8,
) !void {
    try admitRelationalRowsSetOperationRowsWithPolicy(plan, rows, .allow_spill);
}

fn admitRelationalRowsSetOperationRowsWithPolicy(
    plan: types.RelationalRowsSetOperationPlan,
    rows: []const []const u8,
    policy: RelationalRowsCteMaterializationPolicy,
) !void {
    const materialized_bytes = types.relationalRowsCteMaterializedJsonBytes(rows) orelse return error.UnsupportedQueryRequest;
    try admitRelationalRowsMaterializationDecisionWithPolicy(
        types.relationalRowsSetOperationMaterializationDecision(plan, rows.len, materialized_bytes),
        policy,
    );
}

pub fn admitRelationalRowsCteMaterialization(
    cte: types.RelationalRowsCte,
    observed_rows: usize,
    observed_bytes: u64,
) !void {
    try admitRelationalRowsCteMaterializationWithPolicy(cte, observed_rows, observed_bytes, .strict);
}

pub fn admitRelationalRowsCteMaterializationAllowSpill(
    cte: types.RelationalRowsCte,
    observed_rows: usize,
    observed_bytes: u64,
) !void {
    try admitRelationalRowsCteMaterializationWithPolicy(cte, observed_rows, observed_bytes, .allow_spill);
}

const RelationalRowsCteMaterializationPolicy = enum {
    strict,
    allow_spill,
};

fn admitRelationalRowsCteMaterializationWithPolicy(
    cte: types.RelationalRowsCte,
    observed_rows: usize,
    observed_bytes: u64,
    policy: RelationalRowsCteMaterializationPolicy,
) !void {
    try admitRelationalRowsMaterializationDecisionWithPolicy(
        types.relationalRowsCteMaterializationDecision(cte, observed_rows, observed_bytes),
        policy,
    );
}

fn admitRelationalRowsMaterializationDecisionWithPolicy(
    decision: types.RelationalRowsCteMaterializationDecision,
    policy: RelationalRowsCteMaterializationPolicy,
) !void {
    switch (decision) {
        .memory => {},
        .spill => switch (policy) {
            .strict => return error.RelationalRowsCteSpillRequired,
            .allow_spill => {},
        },
        .reject => return error.RelationalRowsCteMaterializationRejected,
    }
}

pub fn relationalRowsSetOperationRowsAlloc(
    alloc: Allocator,
    operation: types.RelationalRowsSetOperation,
    left: []const []const u8,
    right: []const []const u8,
) ![]const []const u8 {
    return switch (operation) {
        .union_all => try relationalRowsUnionAllRowsAlloc(alloc, left, right),
        .union_distinct => try relationalRowsUnionDistinctRowsAlloc(alloc, left, right),
        .intersect => try relationalRowsIntersectRowsAlloc(alloc, left, right),
        .except => try relationalRowsExceptRowsAlloc(alloc, left, right),
    };
}

fn relationalRowsUnionAllRowsAlloc(
    alloc: Allocator,
    left: []const []const u8,
    right: []const []const u8,
) ![]const []const u8 {
    var rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer deinitRelationalRowsSetRowList(alloc, &rows);
    try rows.ensureUnusedCapacity(alloc, left.len + right.len);
    for (left) |row| rows.appendAssumeCapacity(try alloc.dupe(u8, row));
    for (right) |row| rows.appendAssumeCapacity(try alloc.dupe(u8, row));
    return try rows.toOwnedSlice(alloc);
}

fn relationalRowsUnionDistinctRowsAlloc(
    alloc: Allocator,
    left: []const []const u8,
    right: []const []const u8,
) ![]const []const u8 {
    var seen = std.StringHashMapUnmanaged(void).empty;
    defer freeRelationalRowsSetKeyMap(alloc, &seen);
    var rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer deinitRelationalRowsSetRowList(alloc, &rows);
    for (left) |row| try appendDistinctRelationalRowsSetRowAlloc(alloc, &seen, &rows, row);
    for (right) |row| try appendDistinctRelationalRowsSetRowAlloc(alloc, &seen, &rows, row);
    return try rows.toOwnedSlice(alloc);
}

fn relationalRowsIntersectRowsAlloc(
    alloc: Allocator,
    left: []const []const u8,
    right: []const []const u8,
) ![]const []const u8 {
    var right_set = std.StringHashMapUnmanaged(void).empty;
    defer freeRelationalRowsSetKeyMap(alloc, &right_set);
    for (right) |row| _ = try putRelationalRowsSetKeyAlloc(alloc, &right_set, row);

    var emitted = std.StringHashMapUnmanaged(void).empty;
    defer freeRelationalRowsSetKeyMap(alloc, &emitted);
    var rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer deinitRelationalRowsSetRowList(alloc, &rows);
    for (left) |row| {
        if (!right_set.contains(row)) continue;
        try appendDistinctRelationalRowsSetRowAlloc(alloc, &emitted, &rows, row);
    }
    return try rows.toOwnedSlice(alloc);
}

fn relationalRowsExceptRowsAlloc(
    alloc: Allocator,
    left: []const []const u8,
    right: []const []const u8,
) ![]const []const u8 {
    var right_set = std.StringHashMapUnmanaged(void).empty;
    defer freeRelationalRowsSetKeyMap(alloc, &right_set);
    for (right) |row| _ = try putRelationalRowsSetKeyAlloc(alloc, &right_set, row);

    var emitted = std.StringHashMapUnmanaged(void).empty;
    defer freeRelationalRowsSetKeyMap(alloc, &emitted);
    var rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer deinitRelationalRowsSetRowList(alloc, &rows);
    for (left) |row| {
        if (right_set.contains(row)) continue;
        try appendDistinctRelationalRowsSetRowAlloc(alloc, &emitted, &rows, row);
    }
    return try rows.toOwnedSlice(alloc);
}

fn appendDistinctRelationalRowsSetRowAlloc(
    alloc: Allocator,
    seen: *std.StringHashMapUnmanaged(void),
    rows: *std.ArrayListUnmanaged([]const u8),
    row: []const u8,
) !void {
    if (try putRelationalRowsSetKeyAlloc(alloc, seen, row)) {
        const row_copy = try alloc.dupe(u8, row);
        errdefer alloc.free(row_copy);
        try rows.append(alloc, row_copy);
    }
}

fn putRelationalRowsSetKeyAlloc(
    alloc: Allocator,
    set: *std.StringHashMapUnmanaged(void),
    row: []const u8,
) !bool {
    if (set.contains(row)) return false;
    const key = try alloc.dupe(u8, row);
    errdefer alloc.free(key);
    const gop = try set.getOrPut(alloc, key);
    if (gop.found_existing) {
        alloc.free(key);
        return false;
    }
    return true;
}

fn deinitRelationalRowsSetRowList(
    alloc: Allocator,
    rows: *std.ArrayListUnmanaged([]const u8),
) void {
    for (rows.items) |row| alloc.free(@constCast(row));
    rows.deinit(alloc);
}

fn freeRelationalRowsSetKeyMap(
    alloc: Allocator,
    set: *std.StringHashMapUnmanaged(void),
) void {
    var keys = set.keyIterator();
    while (keys.next()) |key| alloc.free(@constCast(key.*));
    set.deinit(alloc);
}

fn freeOwnedConstStringSlice(alloc: Allocator, keys: []const []const u8) void {
    for (keys) |key| alloc.free(@constCast(key));
    if (keys.len > 0) alloc.free(@constCast(keys));
}

fn freeOwnedConstStringArrayList(alloc: Allocator, rows: *std.ArrayListUnmanaged([]const u8)) void {
    for (rows.items) |row| alloc.free(@constCast(row));
    rows.deinit(alloc);
}

test "relational rows window source admission rejects over-cap materialization" {
    const alloc = std.testing.allocator;
    const row = "{}";
    const rows = try alloc.alloc([]const u8, types.default_relational_rows_cte_max_rows + 1);
    defer alloc.free(rows);
    @memset(rows, row);

    try std.testing.expectError(error.RelationalRowsCteMaterializationRejected, admitRelationalRowsWindowSourceRows(rows));
    try admitRelationalRowsWindowSourceRows(rows[0..types.default_relational_rows_cte_max_rows]);

    const small_rows = [_][]const u8{ "{}", "{}" };
    try std.testing.expectError(
        error.RelationalRowsCteMaterializationRejected,
        admitRelationalRowsWindowSourceRowsWithLimits(small_rows[0..], 2, 5),
    );
    try admitRelationalRowsWindowSourceRowsWithLimits(small_rows[0..], 2, 7);
}

test "relational rows window plan computes row_number over ordered partitions" {
    const alloc = std.testing.allocator;
    const table_schema_api = @import("../../schema/mod.zig");
    const DB = @import("mod.zig").DB;

    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"tenant":{"type":"keyword"},"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"}},"required":["tenant","id","status","amount"],"additionalProperties":false}}},"primary_key":{"columns":["tenant","id"]}}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:1", .value = "{\"tenant\":\"t1\",\"id\":\"a\",\"status\":\"open\",\"amount\":30}" },
            .{ .key = "row:2", .value = "{\"tenant\":\"t1\",\"id\":\"b\",\"status\":\"open\",\"amount\":10}" },
            .{ .key = "row:3", .value = "{\"tenant\":\"t1\",\"id\":\"c\",\"status\":\"closed\",\"amount\":20}" },
            .{ .key = "row:4", .value = "{\"tenant\":\"t2\",\"id\":\"d\",\"status\":\"open\",\"amount\":40}" },
            .{ .key = "row:5", .value = "{\"tenant\":\"t2\",\"id\":\"e\",\"status\":\"open\",\"amount\":5}" },
            .{ .key = "row:6", .value = "{\"tenant\":\"t1\",\"id\":\"f\",\"status\":\"open\",\"amount\":30}" },
        },
        .sync_level = .write,
    });

    const open_predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "status", .op = .eq, .value_json = "\"open\"" },
    };
    const partition_by = [_][]const u8{"tenant"};
    const window_order = [_]types.RelationalRowsQueryOrder{.{
        .field = "amount",
        .direction = .desc,
    }};
    const windows = [_]types.RelationalRowsWindowSpec{
        .{
            .output = "row_num",
            .function = .row_number,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
        },
        .{
            .output = "rank",
            .function = .rank,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
        },
        .{
            .output = "dense_rank",
            .function = .dense_rank,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
        },
        .{
            .output = "prev_amount",
            .function = .lag,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
            .default_json = "0",
        },
        .{
            .output = "next_amount",
            .function = .lead,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
        },
        .{
            .output = "first_amount",
            .function = .first_value,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
        },
        .{
            .output = "last_amount",
            .function = .last_value,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
            .frame = .{ .unit = .rows, .end = .unbounded_following },
        },
        .{
            .output = "partition_count",
            .function = .count,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .frame = .{ .unit = .rows, .end = .unbounded_following },
        },
        .{
            .output = "partition_sum",
            .function = .sum,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
            .frame = .{ .unit = .rows, .end = .unbounded_following },
        },
        .{
            .output = "current_avg",
            .function = .avg,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
            .frame = .{ .unit = .rows, .start = .current_row, .end = .current_row },
        },
        .{
            .output = "partition_min",
            .function = .min,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
            .frame = .{ .unit = .rows, .end = .unbounded_following },
        },
        .{
            .output = "partition_max",
            .function = .max,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
            .frame = .{ .unit = .rows, .end = .unbounded_following },
        },
        .{
            .output = "first_status",
            .function = .min,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "status" },
            .frame = .{ .unit = .rows, .end = .unbounded_following },
        },
        .{
            .output = "last_status",
            .function = .max,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "status" },
            .frame = .{ .unit = .rows, .end = .unbounded_following },
        },
        .{
            .output = "tail_count",
            .function = .count,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .frame = .{ .unit = .rows, .start = .current_row, .end = .unbounded_following },
        },
        .{
            .output = "neighbor_count",
            .function = .count,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .frame = .{ .unit = .rows, .start = .offset_preceding, .start_offset = 1, .end = .offset_following, .end_offset = 1 },
        },
        .{
            .output = "next_frame_amount",
            .function = .first_value,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = .{ .kind = .field, .field = "amount" },
            .frame = .{ .unit = .rows, .start = .offset_following, .start_offset = 1, .end = .offset_following, .end_offset = 1 },
        },
        .{
            .output = "range_tail_count",
            .function = .count,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .frame = .{ .unit = .range, .start = .current_row, .end = .offset_following, .end_offset = 25 },
        },
        .{
            .output = "range_count",
            .function = .count,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
        },
    };
    const select = [_][]const u8{ "tenant", "id", "amount" };

    var result = try db.windowRelationalRowsPlan(alloc, runtime_schema, .{
        .window = .{
            .source = .{
                .predicates = open_predicates[0..],
                .select_all = true,
            },
            .windows = windows[0..],
            .select = select[0..],
            .select_all = false,
        },
    });
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 5), result.total_rows);
    try std.testing.expectEqual(@as(usize, 5), result.rows.len);
    try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"a\",\"amount\":30,\"row_num\":1,\"rank\":1,\"dense_rank\":1,\"prev_amount\":0,\"next_amount\":30,\"first_amount\":30,\"last_amount\":10,\"partition_count\":3,\"partition_sum\":70,\"current_avg\":30,\"partition_min\":10,\"partition_max\":30,\"first_status\":\"open\",\"last_status\":\"open\",\"tail_count\":3,\"neighbor_count\":2,\"next_frame_amount\":30,\"range_tail_count\":3,\"range_count\":2}", result.rows[0]);
