test "relational rows window source spill reloads rows and records diagnostics" {
    const alloc = std.testing.allocator;
    var columns = [_]schema_mod.RelationalColumn{
        .{ .name = "id", .path = "id", .field_type = .keyword, .nullable = false },
        .{ .name = "tenant", .path = "tenant", .field_type = .keyword, .nullable = false },
        .{ .name = "amount", .path = "amount", .field_type = .numeric, .nullable = false },
    };
    const rows = [_][]const u8{
        "{\"id\":\"a\",\"tenant\":\"t1\",\"amount\":2}",
        "{\"id\":\"b\",\"tenant\":\"t1\",\"amount\":5}",
        "{\"id\":\"c\",\"tenant\":\"t2\",\"amount\":1}",
    };
    const partition_t1_rows = [_][]const u8{ rows[0], rows[1] };
    const observed_bytes = types.relationalRowsCteMaterializedJsonBytes(rows[0..]) orelse return error.TestUnexpectedResult;
    const t1_partition_bytes = types.relationalRowsCteMaterializedJsonBytes(partition_t1_rows[0..]) orelse return error.TestUnexpectedResult;

    const window_order = [_]types.RelationalRowsQueryOrder{.{
        .field = "amount",
        .direction = .desc,
    }};
    const windows = [_]types.RelationalRowsWindowSpec{.{
        .output = "row_num",
        .function = .row_number,
        .partition_by = &.{"tenant"},
        .order_by = window_order[0..],
    }};
    var result = try windowFromSourceRowsWithColumnsAlloc(alloc, .{
        .windows = windows[0..],
        .select = &.{ "id", "tenant" },
        .spill_after_bytes = 8,
        .max_bytes = observed_bytes,
    }, rows[0..], columns[0..], 0);
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 3), result.total_rows);
    try std.testing.expectEqualStrings("{\"id\":\"a\",\"tenant\":\"t1\",\"row_num\":2}", result.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"b\",\"tenant\":\"t1\",\"row_num\":1}", result.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"c\",\"tenant\":\"t2\",\"row_num\":1}", result.rows[2]);
    try std.testing.expectEqual(@as(u64, 3), result.diagnostics.input_rows);
    try std.testing.expectEqual(@as(u32, 3), result.diagnostics.output_rows);
    try std.testing.expectEqual(observed_bytes, result.diagnostics.source_materialized_bytes);
    try std.testing.expectEqual(@as(u32, 1), result.diagnostics.window_count);
    try std.testing.expectEqual(@as(u64, 2), result.diagnostics.partition_evaluations);
    try std.testing.expectEqual(@as(u64, 2), result.diagnostics.max_partition_rows);
    try std.testing.expectEqual(t1_partition_bytes, result.diagnostics.max_partition_materialized_bytes);
    try std.testing.expectEqual(@as(u64, 1), result.diagnostics.source_spill_writes);
    try std.testing.expectEqual(observed_bytes, result.diagnostics.source_spill_bytes);
    try std.testing.expectEqual(@as(u64, 1), result.diagnostics.source_spill_reload_count);
    try std.testing.expectEqual(@as(u64, 0), result.diagnostics.resource_budget_failures);

    try std.testing.expectError(error.RelationalRowsCteMaterializationRejected, windowFromSourceRowsWithColumnsAlloc(alloc, .{
        .windows = windows[0..],
        .select = &.{"id"},
        .max_rows = 2,
    }, rows[0..], columns[0..], 0));
    try std.testing.expectError(error.RelationalRowsCteMaterializationRejected, windowFromSourceRowsWithColumnsAlloc(alloc, .{
        .windows = windows[0..],
        .select = &.{"id"},
        .max_bytes = observed_bytes - 1,
    }, rows[0..], columns[0..], 0));
}

test "relational rows window plan supports boolean aggregate windows" {
    const alloc = std.testing.allocator;
    const table_schema_api = @import("../../schema/mod.zig");
    const DB = @import("mod.zig").DB;

    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"tenant":{"type":"keyword"},"id":{"type":"keyword"},"status":{"type":"keyword"},"enabled":{"type":"boolean"},"amount":{"type":"numeric"}},"required":["tenant","id","status","amount"],"additionalProperties":false}}},"primary_key":{"columns":["tenant","id"]}}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:1", .value = "{\"tenant\":\"t1\",\"id\":\"a\",\"status\":\"open\",\"enabled\":true,\"amount\":30}" },
            .{ .key = "row:2", .value = "{\"tenant\":\"t1\",\"id\":\"b\",\"status\":\"closed\",\"enabled\":false,\"amount\":20}" },
            .{ .key = "row:3", .value = "{\"tenant\":\"t1\",\"id\":\"c\",\"status\":\"open\",\"amount\":10}" },
            .{ .key = "row:4", .value = "{\"tenant\":\"t2\",\"id\":\"d\",\"status\":\"closed\",\"amount\":5}" },
        },
        .sync_level = .write,
    });

    const partition_by = [_][]const u8{"tenant"};
    const window_order = [_]types.RelationalRowsQueryOrder{.{
        .field = "amount",
        .direction = .desc,
    }};
    const enabled_expression = types.RelationalRowsExpression{ .kind = .field, .field = "enabled" };
    const open_filter = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "status", .op = .eq, .value_json = "\"open\"" },
    };
    const windows = [_]types.RelationalRowsWindowSpec{
        .{
            .output = "running_any_enabled",
            .function = .bool_or,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = enabled_expression,
            .frame = .{ .unit = .rows, .start = .unbounded_preceding, .end = .current_row },
        },
        .{
            .output = "running_all_enabled",
            .function = .bool_and,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = enabled_expression,
            .frame = .{ .unit = .rows, .start = .unbounded_preceding, .end = .current_row },
        },
        .{
            .output = "running_open_count",
            .function = .count,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .frame = .{ .unit = .rows, .start = .unbounded_preceding, .end = .current_row },
            .filter_predicates = open_filter[0..],
        },
        .{
            .output = "current_any_enabled",
            .function = .bool_or,
            .partition_by = partition_by[0..],
            .order_by = window_order[0..],
            .value_expression = enabled_expression,
            .frame = .{ .unit = .rows, .start = .current_row, .end = .current_row },
            .filter_predicates = open_filter[0..],
        },
    };
    const select = [_][]const u8{ "tenant", "id" };
    var result = try db.windowRelationalRowsPlan(alloc, runtime_schema, .{
        .window = .{
            .windows = windows[0..],
            .select = select[0..],
            .select_all = false,
        },
    });
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 4), result.total_rows);
    try std.testing.expectEqual(@as(usize, 4), result.rows.len);
    try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"a\",\"running_any_enabled\":true,\"running_all_enabled\":true,\"running_open_count\":1,\"current_any_enabled\":true}", result.rows[0]);
    try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"b\",\"running_any_enabled\":true,\"running_all_enabled\":false,\"running_open_count\":1,\"current_any_enabled\":null}", result.rows[1]);
    try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"c\",\"running_any_enabled\":true,\"running_all_enabled\":false,\"running_open_count\":2,\"current_any_enabled\":null}", result.rows[2]);
    try std.testing.expectEqualStrings("{\"tenant\":\"t2\",\"id\":\"d\",\"running_any_enabled\":null,\"running_all_enabled\":null,\"running_open_count\":0,\"current_any_enabled\":null}", result.rows[3]);
}

