    try db.claimRowsForTransaction(locker_txn, &.{row_keys[0]}, .{
        .mode = .for_update,
        .owner_id = "session:range-locker",
        .txn_id = locker_txn,
    });

    const mutation_txn = try db.beginTransaction(2_010);
    const predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "status",
        .op = .eq,
        .value_json = "\"ready\"",
    }};
