test "relational rows query planner orders candidate sets by estimated cardinality" {
    const alloc = std.testing.allocator;

    var small = try doc_set.cloneDocKeysAlloc(alloc, &.{"row:small"});
    var medium = try doc_set.fromOrdinalsAlloc(alloc, &.{ 1, 2, 3 });
    var planned = [_]PlannedCandidateSet{
        .{
            .set = .all,
            .estimated_cardinality = null,
            .ordinal = 0,
        },
        .{
            .set = medium,
            .estimated_cardinality = medium.estimatedCardinality(),
            .ordinal = 1,
        },
        .{
            .set = .none,
            .estimated_cardinality = 0,
            .ordinal = 2,
        },
        .{
            .set = small,
            .estimated_cardinality = small.estimatedCardinality(),
            .ordinal = 3,
        },
    };
    medium = .none;
    small = .none;
    defer for (&planned) |*item| item.deinit(alloc);

    std.sort.pdq(PlannedCandidateSet, &planned, {}, plannedCandidateSetLessThan);

    try std.testing.expectEqual(@as(usize, 2), planned[0].ordinal);
    try std.testing.expectEqual(@as(usize, 3), planned[1].ordinal);
    try std.testing.expectEqual(@as(usize, 1), planned[2].ordinal);
    try std.testing.expectEqual(@as(usize, 0), planned[3].ordinal);
}

test "relational rows set operation plan executes typed set semantics" {
    const DB = @import("mod.zig").DB;
    const table_schema_api = @import("../../schema/mod.zig");

    const alloc = std.testing.allocator;
    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"side":{"type":"keyword"}},"required":["id","side"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:a", .value = "{\"id\":\"a\",\"side\":\"left\"}" },
            .{ .key = "row:b", .value = "{\"id\":\"b\",\"side\":\"both\"}" },
            .{ .key = "row:c", .value = "{\"id\":\"c\",\"side\":\"right\"}" },
        },
        .sync_level = .write,
    });

    const select = [_][]const u8{"id"};
    const order_by = [_]types.RelationalRowsQueryOrder{.{
        .field = "id",
        .direction = .asc,
    }};
    const left_values = [_]types.RelationalRowsInPredicate{.{
        .field = "side",
        .values_json = "[\"left\",\"both\"]",
    }};
    const right_values = [_]types.RelationalRowsInPredicate{.{
        .field = "side",
        .values_json = "[\"right\",\"both\"]",
    }};
    const left_plan = types.RelationalRowsQueryPlan{ .query = .{
        .in_predicates = left_values[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
    } };
    const right_plan = types.RelationalRowsQueryPlan{ .query = .{
        .in_predicates = right_values[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
    } };

    var union_all = try db.queryRelationalRowsSetOperationPlan(alloc, runtime_schema, .{
        .operation = .union_all,
        .left = left_plan,
        .right = right_plan,
    });
    defer union_all.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 4), union_all.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", union_all.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", union_all.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", union_all.rows[2]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", union_all.rows[3]);

    var union_distinct = try db.queryRelationalRowsSetOperationPlan(alloc, runtime_schema, .{
        .operation = .union_distinct,
        .left = left_plan,
        .right = right_plan,
    });
    defer union_distinct.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 3), union_distinct.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", union_distinct.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", union_distinct.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", union_distinct.rows[2]);

    var intersect = try db.queryRelationalRowsSetOperationPlan(alloc, runtime_schema, .{
        .operation = .intersect,
        .left = left_plan,
        .right = right_plan,
    });
    defer intersect.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), intersect.total);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", intersect.rows[0]);

    var except = try db.queryRelationalRowsSetOperationPlan(alloc, runtime_schema, .{
        .operation = .except,
        .left = left_plan,
        .right = right_plan,
    });
    defer except.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), except.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", except.rows[0]);

    const tail_order = [_]types.RelationalRowsQueryOrder{.{
        .field = "id",
        .direction = .desc,
    }};
    var globally_ordered = try db.queryRelationalRowsSetOperationPlan(alloc, runtime_schema, .{
        .operation = .union_all,
        .left = left_plan,
        .right = right_plan,
        .order_by = tail_order[0..],
        .limit = 2,
        .offset = 1,
    });
    defer globally_ordered.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 4), globally_ordered.total);
    try std.testing.expectEqual(@as(usize, 2), globally_ordered.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", globally_ordered.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", globally_ordered.rows[1]);

    var spill_admitted = try db.queryRelationalRowsSetOperationPlan(alloc, runtime_schema, .{
        .operation = .union_distinct,
        .left = left_plan,
        .right = right_plan,
        .spill_after_bytes = 8,
    });
    defer spill_admitted.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 3), spill_admitted.total);
    const spill_root = [_]u8{ internal_keys.replay_namespace, internal_keys.relational_cte_spill_kind };
    const leaked_spill_rows = try db.core.store.scanPrefix(alloc, spill_root[0..]);
    defer docstore_mod.DocStore.freeResults(alloc, leaked_spill_rows);
    try std.testing.expectEqual(@as(usize, 0), leaked_spill_rows.len);

    try std.testing.expectError(error.RelationalRowsCteMaterializationRejected, db.queryRelationalRowsSetOperationPlan(alloc, runtime_schema, .{
        .operation = .union_distinct,
        .left = left_plan,
        .right = right_plan,
        .max_rows = 2,
    }));
}

test "relational rows cte spill reloads across reopen and cleans up" {
    const DB = @import("mod.zig").DB;

    const alloc = std.testing.allocator;
    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    const source_rows = [_][]const u8{
        "{\"id\":\"a\",\"amount\":10}",
        "{\"id\":\"b\",\"amount\":20}",
        "{\"id\":\"c\",\"amount\":30}",
    };
    const materialized_bytes = types.relationalRowsCteMaterializedJsonBytes(source_rows[0..]) orelse return error.UnsupportedQueryRequest;
    var spill: RelationalRowsSpilledCte = undefined;
    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        spill = try db.testSpillRelationalRowsCteResultAlloc(alloc, .{
            .rows = @constCast(source_rows[0..]),
            .total = @intCast(source_rows.len),
        }, materialized_bytes);
    }
    defer spill.deinit(alloc);
    try std.testing.expectEqual(source_rows.len, spill.row_count);
    try std.testing.expectEqual(materialized_bytes, spill.materialized_bytes);

    {
        var reopened = try DB.open(alloc, std.mem.span(path), .{});
        defer reopened.close();

        var loaded = try reopened.testLoadRelationalRowsSpilledCteAlloc(alloc, spill);
        defer loaded.deinit(alloc);
        try std.testing.expectEqual(@as(u32, source_rows.len), loaded.total);
        try std.testing.expectEqual(source_rows.len, loaded.rows.len);
        try std.testing.expectEqualStrings(source_rows[0], loaded.rows[0]);
        try std.testing.expectEqualStrings(source_rows[1], loaded.rows[1]);
        try std.testing.expectEqualStrings(source_rows[2], loaded.rows[2]);

        reopened.testDeleteRelationalRowsSpilledCte(alloc, spill);
        const spill_root = [_]u8{ internal_keys.replay_namespace, internal_keys.relational_cte_spill_kind };
        const remaining_spills = try reopened.core.scanStorePrefix(alloc, spill_root[0..]);
        defer docstore_mod.DocStore.freeResults(alloc, remaining_spills);
        try std.testing.expectEqual(@as(usize, 0), remaining_spills.len);
    }
}

test "relational rows query doc key range scopes indexed and scanned candidates" {
    const DB = @import("mod.zig").DB;
    const table_schema_api = @import("../../schema/mod.zig");

    const alloc = std.testing.allocator;
    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric","x-antfly-index":false},"rank":{"type":"numeric"}},"required":["id","status","amount","rank"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:a", .value = "{\"id\":\"a\",\"status\":\"open\",\"amount\":100,\"rank\":1}" },
            .{ .key = "row:b", .value = "{\"id\":\"b\",\"status\":\"open\",\"amount\":20,\"rank\":2}" },
            .{ .key = "row:c", .value = "{\"id\":\"c\",\"status\":\"open\",\"amount\":30,\"rank\":3}" },
            .{ .key = "row:d", .value = "{\"id\":\"d\",\"status\":\"open\",\"amount\":40,\"rank\":4}" },
        },
        .sync_level = .write,
    });

    const indexed_predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "status", .op = .eq, .value_json = "\"open\"" },
    };
    const select = [_][]const u8{"id"};
    const order_by = [_]types.RelationalRowsQueryOrder{.{
        .field = "rank",
        .direction = .asc,
    }};
    var indexed = try db.queryRelationalRows(alloc, runtime_schema, .{
        .predicates = indexed_predicates[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
        .doc_key_range = .{ .start = "row:b", .end = "row:d" },
    });
    defer indexed.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 2), indexed.total);
    try std.testing.expectEqual(@as(usize, 2), indexed.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", indexed.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", indexed.rows[1]);

    const scanned_predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "amount", .op = .gt, .value_json = "10" },
    };
    var scanned = try db.queryRelationalRows(alloc, runtime_schema, .{
        .predicates = scanned_predicates[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
        .doc_key_range = .{ .start = "row:b", .end = "row:d" },
    });
    defer scanned.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 2), scanned.total);
    try std.testing.expectEqual(@as(usize, 2), scanned.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", scanned.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", scanned.rows[1]);
}

test "relational rows query plan composes non-recursive ctes" {
    const DB = @import("mod.zig").DB;
    const table_schema_api = @import("../../schema/mod.zig");

    const alloc = std.testing.allocator;
    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"rank":{"type":"numeric"}},"required":["id","status","amount","rank"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:a", .value = "{\"id\":\"a\",\"status\":\"open\",\"amount\":10,\"rank\":1}" },
            .{ .key = "row:b", .value = "{\"id\":\"b\",\"status\":\"open\",\"amount\":20,\"rank\":2}" },
            .{ .key = "row:c", .value = "{\"id\":\"c\",\"status\":\"closed\",\"amount\":30,\"rank\":3}" },
            .{ .key = "row:d", .value = "{\"id\":\"d\",\"status\":\"open\",\"amount\":40,\"rank\":4}" },
        },
        .sync_level = .write,
    });

    const open_predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "status", .op = .eq, .value_json = "\"open\"" },
    };
    const expensive_predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "amount", .op = .gt, .value_json = "15" },
    };
    const final_predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "amount", .op = .lt, .value_json = "35" },
    };
    const select = [_][]const u8{ "id", "amount" };
    const order_by = [_]types.RelationalRowsQueryOrder{.{
        .field = "amount",
        .direction = .desc,
    }};
    const ctes = [_]types.RelationalRowsCte{
        .{
            .name = "open_orders",
            .query = .{
                .predicates = open_predicates[0..],
                .select_all = true,
            },
        },
        .{
            .name = "expensive_open_orders",
            .query = .{
                .source_cte = "open_orders",
                .predicates = expensive_predicates[0..],
                .select_all = true,
            },
        },
    };
    const default_cte_limits = types.relationalRowsCteMaterializationLimits(ctes[0]);
    try std.testing.expectEqual(types.default_relational_rows_cte_max_rows, default_cte_limits.max_rows);
    try std.testing.expectEqual(types.default_relational_rows_cte_max_bytes, default_cte_limits.max_bytes);
    try std.testing.expectEqual(types.default_relational_rows_cte_spill_after_bytes, default_cte_limits.spill_after_bytes);

    var result = try db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = ctes[0..],
        .query = .{
            .source_cte = "expensive_open_orders",
            .predicates = final_predicates[0..],
            .select = select[0..],
            .select_all = false,
            .order_by = order_by[0..],
        },
    });
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), result.total);
    try std.testing.expectEqual(@as(usize, 1), result.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"b\",\"amount\":20}", result.rows[0]);

    const spill_ctes = [_]types.RelationalRowsCte{.{
        .name = "open_orders",
        .query = .{
            .predicates = open_predicates[0..],
            .select_all = true,
        },
        .spill_after_bytes = 8,
    }};
    var spilled_result = try db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = spill_ctes[0..],
        .query = .{
            .source_cte = "open_orders",
            .select = select[0..],
            .select_all = false,
        },
    });
    defer spilled_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 3), spilled_result.total);
    try std.testing.expectEqual(@as(usize, 3), spilled_result.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"a\",\"amount\":10}", spilled_result.rows[0]);

    const spill_root = [_]u8{ internal_keys.replay_namespace, internal_keys.relational_cte_spill_kind };
    const remaining_spills = try db.core.scanStorePrefix(alloc, spill_root[0..]);
    defer docstore_mod.DocStore.freeResults(alloc, remaining_spills);
    try std.testing.expectEqual(@as(usize, 0), remaining_spills.len);

    try std.testing.expectError(error.UnsupportedQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .query = .{
            .predicates = open_predicates[0..],
            .doc_key_range = .{ .start = "row:a", .end = "row:z" },
        },
    }));
    try std.testing.expectError(error.UnsupportedQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .query = .{
            .predicates = open_predicates[0..],
            .row_claim = .{ .owner_id = "reader" },
        },
    }));

    const projected_select = [_][]const u8{"id"};
    const projected_amount_plus_one = [_]types.RelationalRowsExpressionProjection{.{
        .output = "amount_plus_one",
        .expression = .{
            .kind = .add,
            .operands = &.{
                .{ .kind = .field, .field = "amount" },
                .{ .kind = .value, .value_json = "1" },
            },
        },
    }};
    const projected_ctes = [_]types.RelationalRowsCte{.{
        .name = "projected_orders",
        .query = .{
            .predicates = open_predicates[0..],
            .select = projected_select[0..],
            .expressions = projected_amount_plus_one[0..],
            .select_all = false,
        },
    }};
    const projected_result_select = [_][]const u8{ "id", "amount_plus_one" };
    const projected_order_by = [_]types.RelationalRowsQueryOrder{.{
        .field = "amount_plus_one",
        .direction = .desc,
    }};
    var projected = try db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = projected_ctes[0..],
        .query = .{
            .source_cte = "projected_orders",
            .select = projected_result_select[0..],
            .select_all = false,
            .order_by = projected_order_by[0..],
        },
    });
    defer projected.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 3), projected.total);
    try std.testing.expectEqual(@as(usize, 3), projected.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"d\",\"amount_plus_one\":41}", projected.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"b\",\"amount_plus_one\":21}", projected.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"a\",\"amount_plus_one\":11}", projected.rows[2]);

    const chained_projected_ctes = [_]types.RelationalRowsCte{
        projected_ctes[0],
        .{
            .name = "projected_passthrough",
            .query = .{
                .source_cte = "projected_orders",
                .select_all = true,
            },
        },
    };
    var chained_projected = try db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = chained_projected_ctes[0..],
        .query = .{
            .source_cte = "projected_passthrough",
            .select = projected_result_select[0..],
            .select_all = false,
            .order_by = projected_order_by[0..],
        },
    });
    defer chained_projected.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 3), chained_projected.total);
    try std.testing.expectEqualStrings("{\"id\":\"d\",\"amount_plus_one\":41}", chained_projected.rows[0]);

    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = projected_ctes[0..],
        .query = .{
            .source_cte = "projected_orders",
            .predicates = final_predicates[0..],
            .select = projected_select[0..],
            .select_all = false,
        },
    }));

    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = chained_projected_ctes[0..],
        .query = .{
            .source_cte = "projected_passthrough",
            .predicates = final_predicates[0..],
            .select = projected_select[0..],
            .select_all = false,
        },
    }));

    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = projected_ctes[0..],
        .query = .{
            .source_cte = "projected_orders",
            .select = projected_select[0..],
            .select_all = false,
            .order_by = order_by[0..],
        },
    }));

    const missing_field_expression = [_]types.RelationalRowsExpressionProjection{.{
        .output = "missing_amount_plus_one",
        .expression = .{
            .kind = .add,
            .operands = &.{
                .{ .kind = .field, .field = "amount" },
                .{ .kind = .value, .value_json = "1" },
            },
        },
    }};
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = projected_ctes[0..],
        .query = .{
            .source_cte = "projected_orders",
            .select = projected_select[0..],
            .expressions = missing_field_expression[0..],
            .select_all = false,
        },
    }));

    const capped_projected_ctes = [_]types.RelationalRowsCte{
        .{
            .name = "projected_orders_capped",
            .query = .{
                .predicates = open_predicates[0..],
                .select = projected_select[0..],
                .select_all = false,
            },
            .max_rows = 0,
        },
        .{
            .name = "bad_projected_consumer",
            .query = .{
                .source_cte = "projected_orders_capped",
                .select = &.{"amount"},
                .select_all = false,
            },
        },
    };
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = capped_projected_ctes[0..],
        .query = .{ .source_cte = "bad_projected_consumer" },
    }));

    const capped_ctes = [_]types.RelationalRowsCte{.{
        .name = "open_orders",
        .query = .{
            .predicates = open_predicates[0..],
            .select_all = true,
        },
        .max_rows = 2,
    }};
    try std.testing.expectError(error.RelationalRowsCteMaterializationRejected, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = capped_ctes[0..],
        .query = .{ .source_cte = "open_orders" },
    }));

    const byte_capped_ctes = [_]types.RelationalRowsCte{.{
        .name = "open_orders",
        .query = .{
            .predicates = open_predicates[0..],
            .select_all = true,
        },
        .max_bytes = 1,
    }};
    try std.testing.expectError(error.RelationalRowsCteMaterializationRejected, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = byte_capped_ctes[0..],
        .query = .{ .source_cte = "open_orders" },
    }));

    const id_a_predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "id", .op = .eq, .value_json = "\"a\"" },
    };
    const cte_row_payload_only_cap = [_]types.RelationalRowsCte{.{
        .name = "single_id",
        .query = .{
            .predicates = id_a_predicates[0..],
            .select = projected_select[0..],
            .select_all = false,
        },
        .max_bytes = "{\"id\":\"a\"}".len,
    }};
    try std.testing.expectError(error.RelationalRowsCteMaterializationRejected, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = cte_row_payload_only_cap[0..],
        .query = .{ .source_cte = "single_id" },
    }));

    const duplicate_ctes = [_]types.RelationalRowsCte{
        .{
            .name = "open_orders",
            .query = .{
                .predicates = open_predicates[0..],
                .select_all = true,
            },
        },
        .{
            .name = "open_orders",
            .query = .{
                .select_all = true,
            },
        },
    };
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = duplicate_ctes[0..],
        .query = .{ .source_cte = "open_orders" },
    }));

    const range_ctes = [_]types.RelationalRowsCte{
        .{
            .name = "open_orders",
            .query = .{
                .predicates = open_predicates[0..],
                .select_all = true,
            },
        },
        .{
            .name = "range_orders",
            .query = .{
                .doc_key_range = .{ .start = "row:a", .end = "row:z" },
                .select_all = true,
            },
        },
    };
    try std.testing.expectError(error.UnsupportedQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = range_ctes[0..],
        .query = .{ .source_cte = "range_orders" },
    }));

    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = projected_ctes[0..],
        .query = .{ .source_cte = "missing_orders" },
    }));

    try std.testing.expectError(error.UnsupportedQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = projected_ctes[0..],
        .query = .{
            .source_cte = "projected_orders",
            .row_claim = .{ .owner_id = "reader" },
        },
    }));

    try std.testing.expectError(error.UnsupportedQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = projected_ctes[0..],
        .query = .{
            .source_cte = "projected_orders",
            .doc_key_range = .{ .start = "row:a", .end = "row:z" },
        },
    }));

    const forward_ref = [_]types.RelationalRowsCte{.{
        .name = "bad",
        .query = .{
            .source_cte = "later",
            .select_all = true,
        },
    }};
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = forward_ref[0..],
        .query = .{ .source_cte = "bad" },
    }));

    const forward_ref_after_valid = [_]types.RelationalRowsCte{
        projected_ctes[0],
        .{
            .name = "bad",
            .query = .{
                .source_cte = "later",
                .select_all = true,
            },
        },
    };
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRowsPlan(alloc, runtime_schema, .{
        .ctes = forward_ref_after_valid[0..],
        .query = .{ .source_cte = "bad" },
    }));
}

