            .{ .key = "row:a", .value = "{\"tenant\":\"t1\",\"id\":\"o1\",\"status\":\"open\",\"amount\":12}" },
            .{ .key = "row:b", .value = "{\"tenant\":\"t1\",\"id\":\"o2\",\"status\":\"open\",\"amount\":99}" },
        },
        .sync_level = .write,
    });

