    const owner = try db.core.store.get(alloc, owner_key);
    defer alloc.free(owner);
    try std.testing.expectEqualStrings("row:a", owner);

    const id_index_key = try internal_keys.relationalColumnIndexKeyAlloc(alloc, "id", "row:a");
