test "relational rows expression partial predicate implication honors source column collation" {
    const alloc = std.testing.allocator;
    const columns = [_]schema_mod.RelationalColumn{
        .{ .name = "status", .path = "status", .field_type = .keyword, .collation = "antfly.case_insensitive" },
    };
    const exact_columns = [_]schema_mod.RelationalColumn{
        .{ .name = "status", .path = "status", .field_type = .keyword },
    };
    const predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "status",
        .op = .eq,
        .value_json = "\"ACTIVE\"",
    }};
    const rhs = [_]types.RelationalRowsExpression{.{ .kind = .value, .value_json = "\"active\"" }};
    const required = [_]types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .field, .field = "status" },
        .op = .eq,
        .rhs = rhs[0..],
    }};
    const implications = PredicateImplications{ .predicates = predicates[0..] };

    try std.testing.expect(try expressionPredicatesImplyWithColumns(alloc, implications, required[0..], columns[0..], currentTimeNs()));
    try std.testing.expect(!try expressionPredicatesImplyWithColumns(alloc, implications, required[0..], exact_columns[0..], currentTimeNs()));

    const null_predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "status",
        .op = .eq,
        .value_json = "null",
    }};
    const null_implications = PredicateImplications{ .predicates = null_predicates[0..] };
    try std.testing.expect(!try expressionPredicatesImplyWithColumns(alloc, null_implications, required[0..], columns[0..], currentTimeNs()));

    const numeric_columns = [_]schema_mod.RelationalColumn{
        .{ .name = "amount", .path = "amount", .field_type = .numeric },
    };
    const string_amount_predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "amount",
        .op = .eq,
        .value_json = "\"5\"",
    }};
    const numeric_rhs = [_]types.RelationalRowsExpression{.{ .kind = .value, .value_json = "5" }};
    const numeric_required = [_]types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .field, .field = "amount" },
        .op = .eq,
        .rhs = numeric_rhs[0..],
    }};
    const string_amount_implications = PredicateImplications{ .predicates = string_amount_predicates[0..] };
    try std.testing.expect(!try expressionPredicatesImplyWithColumns(alloc, string_amount_implications, numeric_required[0..], numeric_columns[0..], currentTimeNs()));

    const volatile_rhs = [_]types.RelationalRowsExpression{.{ .kind = .value, .value_json = "1234" }};
    const volatile_required = [_]types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .now },
        .op = .eq,
        .rhs = volatile_rhs[0..],
    }};
    const empty_implications = PredicateImplications{};
    try std.testing.expect(!try expressionPredicatesImplyWithColumns(alloc, empty_implications, volatile_required[0..], &.{}, 1234));
}

test "relational rows query row claim skip locked returns claimed subset" {
    const alloc = std.testing.allocator;
    const table_schema_api = @import("../../schema/mod.zig");
    const DB = @import("mod.zig").DB;

    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"rank":{"type":"numeric"},"metadata":{"type":"json"}},"required":["id","status","rank"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:locked", .value = "{\"id\":\"locked\",\"status\":\"ready\",\"rank\":1}" },
            .{ .key = "row:free", .value = "{\"id\":\"free\",\"status\":\"ready\",\"rank\":2}" },
        },
        .timestamp_ns = 1_000,
    });

    const locker_txn = try db.beginTransaction(2_000);
    try db.claimRowsForTransaction(locker_txn, &.{"row:locked"}, .{
        .mode = .for_update,
        .owner_id = "session:locker",
        .txn_id = locker_txn,
    });

    const query_txn = try db.beginTransaction(2_001);
    const predicates = [_]schema_mod.RelationalCheck{
        .{ .name = "", .field = "status", .op = .eq, .value_json = "\"ready\"" },
    };
    const order_by = [_]types.RelationalRowsQueryOrder{.{
        .field = "rank",
        .direction = .asc,
    }};
    const select = [_][]const u8{"id"};
    const distinct_on = [_][]const u8{"status"};
    const claim_request = types.RowClaimRequest{
        .mode = .for_update,
        .skip_locked = true,
        .owner_id = "session:query",
        .txn_id = query_txn,
    };
    try std.testing.expectError(error.UnsupportedQueryRequest, db.queryRelationalRows(alloc, runtime_schema, .{
        .predicates = predicates[0..],
        .select = select[0..],
        .select_all = false,
        .distinct_on = distinct_on[0..],
        .order_by = order_by[0..],
        .row_claim = claim_request,
    }));
    const ranges = [_]types.RelationalRowsDocKeyRange{.{
        .start = "row:",
        .end = "row:z",
    }};
    try std.testing.expectError(error.UnsupportedQueryRequest, db.queryRelationalRowsAcrossRanges(alloc, runtime_schema, .{
        .predicates = predicates[0..],
        .select = select[0..],
        .select_all = false,
        .distinct_on = distinct_on[0..],
        .order_by = order_by[0..],
        .row_claim = claim_request,
    }, ranges[0..]));
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRows(alloc, runtime_schema, .{
        .predicates = predicates[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
        .row_claim = .{
            .mode = .for_update,
            .owner_id = "session:query-missing-txn",
        },
    }));
    const no_match_predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "status",
        .op = .eq,
        .value_json = "\"missing\"",
    }};
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRows(alloc, runtime_schema, .{
        .predicates = no_match_predicates[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
        .row_claim = .{
            .mode = .for_update,
            .txn_id = query_txn,
        },
    }));
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRows(alloc, runtime_schema, .{
        .predicates = no_match_predicates[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
        .row_claim = .{
            .mode = .for_update,
            .owner_id = "session:query-missing-lease",
            .lease_ms = 0,
            .txn_id = query_txn,
        },
    }));

    var claimed = try db.queryRelationalRows(alloc, runtime_schema, .{
        .predicates = predicates[0..],
        .select = select[0..],
        .select_all = false,
        .order_by = order_by[0..],
        .row_claim = claim_request,
        .limit = 10,
    });
    defer claimed.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), claimed.total);
    try std.testing.expectEqual(@as(usize, 1), claimed.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"free\"}", claimed.rows[0]);

    const blocked_txn = try db.beginTransaction(2_002);
    try std.testing.expectError(transactions_mod.TxnError.IntentConflict, db.writeTransaction(blocked_txn, .{
        .writes = &.{.{ .key = "row:free", .value = "{\"id\":\"free\",\"status\":\"blocked\",\"rank\":3}" }},
    }));
}

