            .expression = .{ .kind = .date_part, .operands = created_decade_operands[0..] },
        },
        .{
            .output = "created_century_part",
            .expression = .{ .kind = .date_part, .operands = created_century_operands[0..] },
        },
        .{
            .output = "created_millennium_part",
            .expression = .{ .kind = .date_part, .operands = created_millennium_operands[0..] },
        },
        .{
            .output = "tag_count",
            .expression = .{ .kind = .array_length, .operands = tag_count_operands[0..] },
        },
        .{
            .output = "plan_text",
            .expression = .{
                .kind = .json_extract,
                .json_path = "billing.plan",
                .json_as_text = true,
                .operands = attrs_operands[0..],
            },
        },
        .{
            .output = "has_flags",
            .expression = .{
                .kind = .json_path_exists,
                .json_path = "flags",
                .operands = attrs_operands[0..],
            },
        },
    };
    const order_by = [_]types.RelationalRowsQueryOrder{.{
        .field = "created_at",
        .direction = .desc,
    }};
    var result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .select = select[0..],
        .select_all = false,
        .expressions = expressions[0..],
        .order_by = order_by[0..],
        .limit = 1,
    });
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 2), result.total);
    try std.testing.expectEqual(@as(usize, 1), result.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"a\",\"status_key\":\"active\",\"next_created\":31,\"created_remainder\":2,\"next_cycle\":2678400000000030,\"status_slice\":\"CTI\",\"status_part\":\"IVE\",\"status_t_pos\":3,\"status_left\":\"AC\",\"status_right\":\"VE\",\"status_btrim\":\"ACTIVE\",\"status_ltrim\":\"ACTIVE--\",\"status_rtrim\":\"--ACTIVE\",\"status_lpad\":\"xyACTIVE\",\"status_rpad\":\"ACTIVEzz\",\"status_repeat\":\"ACTIVEACTIVE\",\"status_reverse\":\"EVITCA\",\"status_starts\":true,\"created_hour\":93600000000000,\"created_hour_part\":2,\"created_decade_trunc\":1577836800000000000,\"created_century_trunc\":978307200000000000,\"created_millennium_trunc\":978307200000000000,\"created_decade_part\":202,\"created_century_part\":21,\"created_millennium_part\":3,\"tag_count\":2,\"plan_text\":\"pro\",\"has_flags\":true}", result.rows[0]);

    const select_all_extra_expressions = [_]types.RelationalRowsExpressionProjection{.{
        .output = "status_key",
        .expression = .{ .kind = .lower, .operands = lower_status_operands[0..] },
    }};
    var select_all_extra = try db.queryRelationalRows(alloc, runtime_schema, .{
        .select_all = true,
        .expressions = select_all_extra_expressions[0..],
        .order_by = order_by[0..],
        .limit = 1,
    });
    defer select_all_extra.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), select_all_extra.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\",\"status\":\"ACTIVE\",\"tags\":[\"hot\",\"new\"],\"attrs\":{\"billing\":{\"plan\":\"pro\"},\"flags\":[\"rated\"]},\"created_at\":30,\"status_key\":\"active\"}", select_all_extra.rows[0]);

    const colliding_select_all_expressions = [_]types.RelationalRowsExpressionProjection{.{
        .output = "id",
        .expression = .{ .kind = .lower, .operands = lower_status_operands[0..] },
    }};
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRows(alloc, runtime_schema, .{
        .select_all = true,
        .expressions = colliding_select_all_expressions[0..],
    }));
    const source_scoped_lower_status_operands = [_]types.RelationalRowsExpression{.{
        .kind = .field,
        .field = "status",
        .field_source = .source,
    }};
    const source_scoped_expressions = [_]types.RelationalRowsExpressionProjection{.{
        .output = "status_key",
        .expression = .{ .kind = .lower, .operands = source_scoped_lower_status_operands[0..] },
    }};
    try std.testing.expectError(error.InvalidQueryRequest, db.queryRelationalRows(alloc, runtime_schema, .{
        .select = select[0..],
        .select_all = false,
        .expressions = source_scoped_expressions[0..],
    }));
}

test "relational rows subquery predicates use sql null and empty-set semantics" {
    const alloc = std.testing.allocator;
    const table_schema_api = @import("../../schema/mod.zig");
    const DB = @import("mod.zig").DB;

    var path_buf: [256]u8 = undefined;
    const path = TestHelpers.tempPath(&path_buf);
    defer TestHelpers.cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"pattern":{"type":"keyword"},"rank":{"type":"numeric"}},"required":["id","rank"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:a", .value = "{\"id\":\"a\",\"status\":\"open\",\"pattern\":\"OP%\",\"rank\":1}" },
            .{ .key = "row:b", .value = "{\"id\":\"b\",\"status\":null,\"pattern\":null,\"rank\":2}" },
            .{ .key = "row:c", .value = "{\"id\":\"c\",\"status\":\"closed\",\"pattern\":\"cl%\",\"rank\":3}" },
        },
        .sync_level = .write,
    });

    const select_id = [_][]const u8{"id"};
    const select_status = [_][]const u8{"status"};
    const select_pattern = [_][]const u8{"pattern"};
    const select_rank = [_][]const u8{"rank"};
    const order_by_id = [_]types.RelationalRowsQueryOrder{.{
        .field = "id",
        .direction = .asc,
    }};
    const lhs_status = types.RelationalRowsExpression{ .kind = .field, .field = "status" };
    const lhs_rank = types.RelationalRowsExpression{ .kind = .field, .field = "rank" };
    const rank_is_one = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "rank",
        .op = .eq,
        .value_json = "1",
    }};
    const rank_is_two = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "rank",
        .op = .eq,
        .value_json = "2",
    }};
    const rank_is_three = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "rank",
        .op = .eq,
        .value_json = "3",
    }};
    const rank_is_missing = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "rank",
        .op = .eq,
        .value_json = "99",
    }};

    const in_closed = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .in,
        .lhs = lhs_status,
        .query = .{
            .predicates = rank_is_three[0..],
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
    }};
    var in_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = in_closed[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer in_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), in_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", in_result.rows[0]);

    const status_correlation = [_]types.RelationalRowsLateralCorrelation{.{
        .left_field = "status",
        .right_field = "status",
    }};
    const correlated_exists = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .exists,
        .query = .{},
        .correlations = status_correlation[0..],
    }};
    var correlated_exists_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = correlated_exists[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer correlated_exists_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), correlated_exists_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", correlated_exists_result.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", correlated_exists_result.rows[1]);

    const filtered_correlated_exists = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .exists,
        .query = .{
            .predicates = rank_is_one[0..],
        },
        .correlations = status_correlation[0..],
    }};
    var filtered_correlated_exists_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = filtered_correlated_exists[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer filtered_correlated_exists_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), filtered_correlated_exists_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", filtered_correlated_exists_result.rows[0]);

    const correlated_not_exists = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .exists,
        .negated = true,
        .query = .{},
        .correlations = status_correlation[0..],
    }};
    var correlated_not_exists_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = correlated_not_exists[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer correlated_not_exists_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), correlated_not_exists_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", correlated_not_exists_result.rows[0]);

    const correlated_scalar_status = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .scalar,
        .lhs = lhs_status,
        .query = .{
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
        .correlations = status_correlation[0..],
    }};
    var correlated_scalar_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = correlated_scalar_status[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer correlated_scalar_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), correlated_scalar_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", correlated_scalar_result.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", correlated_scalar_result.rows[1]);

    const correlated_in_status = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .in,
        .lhs = lhs_status,
        .query = .{
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
        .correlations = status_correlation[0..],
    }};
    var correlated_in_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = correlated_in_status[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer correlated_in_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), correlated_in_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", correlated_in_result.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", correlated_in_result.rows[1]);

    const correlated_not_in_status = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .in,
        .lhs = lhs_status,
        .negated = true,
        .query = .{
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
        .correlations = status_correlation[0..],
    }};
    var correlated_not_in_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = correlated_not_in_status[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer correlated_not_in_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), correlated_not_in_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", correlated_not_in_result.rows[0]);

    const correlated_any_status = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .quantified,
        .lhs = lhs_status,
        .quantifier = .any,
        .query = .{
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
        .correlations = status_correlation[0..],
    }};
    var correlated_any_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = correlated_any_status[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer correlated_any_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), correlated_any_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", correlated_any_result.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", correlated_any_result.rows[1]);

    const nested_in_closed_inner = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .in,
        .lhs = lhs_status,
        .query = .{
            .predicates = rank_is_three[0..],
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
    }};
    const nested_in_closed_outer = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .in,
        .lhs = lhs_status,
        .query = .{
            .subquery_predicates = nested_in_closed_inner[0..],
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
    }};
    var nested_in_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = nested_in_closed_outer[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer nested_in_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), nested_in_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", nested_in_result.rows[0]);

    const not_in_null = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .in,
        .lhs = lhs_status,
        .negated = true,
        .query = .{
            .predicates = rank_is_two[0..],
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
    }};
    var not_in_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = not_in_null[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer not_in_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 0), not_in_result.total);

    const any_empty = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .quantified,
        .lhs = lhs_status,
        .quantifier = .any,
        .query = .{
            .predicates = rank_is_missing[0..],
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
    }};
    var any_empty_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = any_empty[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer any_empty_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 0), any_empty_result.total);

    const any_closed = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .quantified,
        .lhs = lhs_status,
        .quantifier = .any,
        .query = .{
            .predicates = rank_is_three[0..],
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
    }};
    var any_closed_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = any_closed[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer any_closed_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), any_closed_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", any_closed_result.rows[0]);

    const all_empty = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .quantified,
        .lhs = lhs_status,
        .quantifier = .all,
        .query = .{
            .predicates = rank_is_missing[0..],
            .select = select_status[0..],
            .select_all = false,
        },
        .output_field = "status",
    }};
    var all_empty_result = try db.queryRelationalRows(alloc, runtime_schema, .{
        .subquery_predicates = all_empty[0..],
        .select = select_id[0..],
        .select_all = false,
        .order_by = order_by_id[0..],
    });
    defer all_empty_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 3), all_empty_result.total);
    try std.testing.expectEqualStrings("{\"id\":\"a\"}", all_empty_result.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"b\"}", all_empty_result.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"c\"}", all_empty_result.rows[2]);

    const gt_any_rank_one = [_]types.RelationalRowsSubqueryPredicate{.{
        .kind = .quantified,
        .lhs = lhs_rank,
        .op = .gt,
